import React, { useState, useEffect, useRef } from 'react';
import { Mic, Phone, AlertCircle, CalendarCheck, Database, Loader2 } from 'lucide-react';
import { connectLiveSession } from '../services/geminiService';
import AudioVisualizer from './AudioVisualizer';
import { Language } from '../types';
import { UI_TRANSLATIONS } from '../constants';

interface CallTabProps {
  emergencyMode?: boolean;
  language: Language;
}

const CallTab: React.FC<CallTabProps> = ({ emergencyMode, language }) => {
  const t = UI_TRANSLATIONS[language];

  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [audioData, setAudioData] = useState<Uint8Array>(new Uint8Array(64));
  const [activeTool, setActiveTool] = useState<string | null>(null);

  const disconnectRef = useRef<(() => Promise<void>) | null>(null);

  useEffect(() => {
    return () => {
      if (disconnectRef.current) {
        disconnectRef.current();
      }
    };
  }, []);

  // Clear tool status after delay
  useEffect(() => {
    if (activeTool) {
      const timer = setTimeout(() => setActiveTool(null), 3500);
      return () => clearTimeout(timer);
    }
  }, [activeTool]);

  const mapErrorToUserMessage = (error: Error): string => {
    const msg = error.message;
    if (language === 'en') {
        if (msg.includes("API_KEY_MISSING")) return "Configuration Error: API Key missing.";
        if (msg.includes("MIC_PERMISSION_DENIED")) return "Microphone access denied. Please check settings.";
        if (msg.includes("MIC_NOT_FOUND")) return "No microphone detected.";
        if (msg.includes("CONNECTION_ERROR")) return "Network connection interrupted.";
        return "An unexpected error occurred.";
    } else {
        if (msg.includes("API_KEY_MISSING")) return "Error de Configuración: Falta API Key.";
        if (msg.includes("MIC_PERMISSION_DENIED")) return "Acceso al micrófono denegado.";
        if (msg.includes("MIC_NOT_FOUND")) return "Micrófono no encontrado.";
        if (msg.includes("CONNECTION_ERROR")) return "Conexión interrumpida.";
        return "Ocurrió un error inesperado.";
    }
  };

  const handleStartCall = async () => {
    setStatus('connecting');
    setErrorMessage('');

    try {
      const session = await connectLiveSession({
        onOpen: () => {
          setStatus('connected');
        },
        onMessage: (text, audioBuffer, interrupted) => {
           // handled by service
        },
        onAudioData: (data) => {
            setAudioData(data);
        },
        onToolCall: (toolName) => {
            setActiveTool(toolName);
        },
        onError: (err) => {
          console.error("Live Session Error:", err);
          setErrorMessage(mapErrorToUserMessage(err));
          setStatus('error');
        },
        onClose: () => {
          setStatus('idle');
        }
      }, emergencyMode, language);

      if (!session) {
        return;
      }

      disconnectRef.current = session.disconnect;

    } catch (e: any) {
      console.error(e);
      setErrorMessage(mapErrorToUserMessage(e));
      setStatus('error');
    }
  };

  const handleEndCall = async () => {
    if (disconnectRef.current) {
      await disconnectRef.current();
      disconnectRef.current = null;
    }
    setStatus('idle');
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 relative overflow-hidden font-sans">

      {/* Top Status Area - Clean & Minimal */}
      <div className="pt-10 pb-4 text-center z-10 px-6 transition-opacity duration-300">
        <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">{t.voiceTitle}</h2>
        <div className={`text-xl font-light tracking-tight transition-colors duration-300 ${
            status === 'error' ? 'text-red-600' : 
            status === 'connected' ? 'text-slate-800' : 'text-slate-500'
        }`}>
          {status === 'idle' && t.tapToStart}
          {status === 'connecting' && (
              <span className="animate-pulse">{t.connecting}</span>
          )}
          {status === 'connected' && t.connected}
          {status === 'error' && t.connectionFailed}
        </div>
      </div>

      {/* Visualizer / Centerpiece */}
      <div className="flex-1 relative flex flex-col items-center justify-center min-h-[300px]">

        {/* Pro Tool Status Indicator - Sleek Badge */}
        <div className={`absolute top-0 z-30 transition-all duration-500 ease-out transform ${
            activeTool ? 'translate-y-2 opacity-100' : '-translate-y-4 opacity-0'
        }`}>
            <div className="bg-slate-900/95 backdrop-blur-sm text-white px-5 py-2.5 rounded-full shadow-2xl flex items-center gap-3 border border-slate-700/50">
                {activeTool === 'book_appointment' ? (
                    <CalendarCheck size={14} className="text-emerald-400" />
                ) : activeTool === 'log_to_crm' ? (
                    <Database size={14} className="text-sky-400" />
                ) : (
                    <Loader2 size={14} className="text-slate-400 animate-spin" />
                )}

                <div className="flex flex-col leading-none">
                    <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">System Action</span>
                    <span className="text-xs font-semibold tracking-wide">
                        {activeTool === 'book_appointment' ? 'Syncing Calendar' : 
                         activeTool === 'log_to_crm' ? 'Updating CRM' : 'Processing...'}
                    </span>
                </div>
            </div>
        </div>

        <div className="relative z-10 w-full flex flex-col items-center justify-center space-y-12">
            {/* The Visualizer */}
            <div className={`h-[100px] w-full flex items-center justify-center px-8 transition-opacity duration-500 ${activeTool ? 'opacity-30' : 'opacity-100'}`}>
                <AudioVisualizer audioData={audioData} isActive={status === 'connected'} />
            </div>

            {/* Mic Button with Contextual Ring Animation */}
            <div className="relative group">
                {/* Active Tool Pulse Ring */}
                {activeTool && (
                    <div className="absolute inset-0 rounded-full border border-sky-400/30 animate-ping" />
                )}

                <div 
                    onClick={status === 'idle' ? handleStartCall : undefined}
                    className={`relative w-20 h-20 rounded-full flex items-center justify-center transition-all duration-500 shadow-xl ${
                    status === 'connected' 
                        ? activeTool 
                            ? 'bg-slate-900 scale-100 ring-2 ring-sky-500/50' // Tool active state
                            : 'bg-white scale-110 ring-1 ring-slate-200'    // Normal listening state
                        : status === 'error' 
                        ? 'bg-red-50 border-2 border-red-200'
                        : 'bg-slate-900 cursor-pointer hover:scale-105 hover:shadow-2xl'
                    }`}
                >
                    {status === 'connected' ? (
                        activeTool ? (
                             <Loader2 size={24} className="text-sky-400 animate-spin" />
                        ) : (
                             <div className="relative">
                                 <div className="absolute inset-0 bg-brand-500 blur-lg opacity-20 animate-pulse"></div>
                                 <Mic size={24} className="text-brand-600 relative z-10" />
                             </div>
                        )
                    ) : status === 'error' ? (
                        <AlertCircle size={24} className="text-red-500" />
                    ) : status === 'connecting' ? (
                         <Loader2 size={24} className="text-white animate-spin" />
                    ) : (
                        <Mic size={24} className="text-white" />
                    )}
                </div>
            </div>
        </div>
      </div>

      {/* Controls Area */}
      <div className="w-full p-8 pt-0 space-y-6 shrink-0 z-10">

        {/* Suggestions - Subtle fade out when connected */}
        <div className={`transition-all duration-500 ${status === 'idle' ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none hidden'}`}>
            <p className="text-[10px] text-center text-slate-400 font-bold uppercase tracking-widest mb-3">{t.tryAsking}</p>
            <div className="grid grid-cols-1 gap-2">
              {t.suggestions.slice(0, 3).map((s, i) => (
                <button 
                  key={i} 
                  className="bg-white border border-slate-200 p-3 rounded-lg text-sm text-slate-600 text-center shadow-sm hover:border-brand-300 hover:text-brand-700 transition-all"
                  onClick={handleStartCall} // Optional: click suggestion to start
                >
                  "{s}"
                </button>
              ))}
            </div>
        </div>

        {status === 'error' && (
          <div className="bg-red-50/50 backdrop-blur border border-red-100 text-red-700 text-sm p-4 rounded-xl text-center">
            <p className="font-medium mb-2">{errorMessage}</p>
            <button 
                onClick={() => setStatus('idle')}
                className="text-xs font-bold uppercase tracking-wide text-red-800 hover:text-red-950 border-b border-red-300 pb-0.5"
            >
                Reset Connection
            </button>
          </div>
        )}

        {status === 'idle' && (
          <button 
            onClick={handleStartCall}
            className="w-full bg-slate-900 text-white font-medium text-sm tracking-wide uppercase py-4 rounded-xl shadow-lg hover:bg-slate-800 transition-transform active:scale-[0.98]"
          >
            {t.startConversation}
          </button>
        )}

        {/* End Call Button - Only visible when connected */}
        {status === 'connected' && (
          <div className="flex justify-center pt-4">
            <button 
              onClick={handleEndCall}
              className="group flex items-center gap-2 px-6 py-3 bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
            >
              <Phone size={18} className="rotate-[135deg]" />
              <span className="text-xs font-bold uppercase tracking-widest">{t.endCall}</span>
            </button>
          </div>
        )}

        {status !== 'idle' && status !== 'error' && (
          <p className="text-[10px] text-center text-slate-300 font-medium tracking-widest uppercase mt-4">
            {t.secureConnection}
          </p>
        )}
      </div>
    </div>
  );
};

export default CallTab;

import { GoogleGenAI, Chat, LiveServerMessage, Modality, FunctionCall } from "@google/genai";
import { getSystemInstruction, TOOLS } from "../constants";
import { createBlob, decodeAudioData, base64ToUint8Array, blobToBase64 } from "../utils/audioUtils";
import { Language } from "../types";

const API_KEY = process.env.API_KEY || ''; 

// Validate API Key immediately
const getAIClient = () => {
  if (!API_KEY) {
    throw new Error("API_KEY_MISSING");
  }
  return new GoogleGenAI({ apiKey: API_KEY });
};

// --- Mock CRM / Backend Actions ---
export const mockBookAppointment = async (data: any) => {
  console.log("Backend: Booking appointment...", data);
  try {
    // Simulate API latency
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Simulate basic validation
    if (!data.date || !data.customerName) {
      throw new Error("Missing required booking fields");
    }

    return { status: "success", confirmationId: "APT-" + Math.floor(Math.random() * 10000) };
  } catch (error) {
    console.error("Booking failed:", error);
    return { status: "error", message: "Failed to book appointment" };
  }
};

export const mockLogToCRM = async (data: any) => {
  console.log("Backend: Logging to CRM...", data);
  try {
    const logsString = localStorage.getItem('unitec_crm_logs') || '[]';
    let logs = [];
    try {
      logs = JSON.parse(logsString);
      if (!Array.isArray(logs)) logs = [];
    } catch (e) {
      console.warn("Corrupt CRM logs found, resetting.", e);
      logs = [];
    }

    logs.unshift({
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      customerName: "Walk-in / Voice User",
      summary: data.summary || "No summary provided",
      actionTaken: data.actionTaken || "General Inquiry",
      sentiment: data.sentiment || "Neutral"
    });
    localStorage.setItem('unitec_crm_logs', JSON.stringify(logs));
    return { status: "logged" };
  } catch (error) {
    console.error("CRM Log failed:", error);
    return { status: "error", message: "Failed to log interaction" };
  }
};

// --- Chat Service ---

let chatSession: Chat | null = null;
let currentLanguage: Language = 'en';

// Helper to reset session if needed (e.g. emergency mode toggle or language change)
export const resetChatSession = () => {
  chatSession = null;
};

export const getChatSession = (emergencyMode: boolean = false, language: Language = 'en') => {
  if (!chatSession || currentLanguage !== language) {
    const ai = getAIClient();
    let instructions = getSystemInstruction(language);
    currentLanguage = language;

    if (emergencyMode) {
      instructions += "\n\n[SYSTEM OVERRIDE: EMERGENCY MODE ACTIVE]. Respond concisely. Prioritize safety protocols immediately.";
    }

    chatSession = ai.chats.create({
      model: 'gemini-2.5-flash',
      config: {
        systemInstruction: instructions,
        tools: [{ functionDeclarations: TOOLS }],
      },
    });
  }
  return chatSession;
};

export async function* sendMessageToGemini(
  message: string, 
  emergencyMode: boolean = false, 
  language: Language = 'en',
  onToolSuccess?: (toolName: string, result: any) => void
) {
  try {
    const session = getChatSession(emergencyMode, language);
    let responseStream = await session.sendMessageStream({ message });

    while (true) {
        let toolCalls: FunctionCall[] = [];

        for await (const chunk of responseStream) {
            // Check for tool calls
            const fc = chunk.functionCalls;
            if (fc && fc.length > 0) {
                toolCalls.push(...fc);
            }

            // Yield text content if present
            if (chunk.text) {
                yield chunk;
            }
        }

        if (toolCalls.length > 0) {
            const functionResponses = [];
            for (const call of toolCalls) {
                let result = {};
                if (call.name === 'book_appointment') {
                    result = await mockBookAppointment(call.args);
                    if ((result as any).status === 'success') {
                        onToolSuccess?.(call.name, result);
                    }
                } else if (call.name === 'log_to_crm') {
                    result = await mockLogToCRM(call.args);
                    if ((result as any).status === 'logged') {
                        onToolSuccess?.(call.name, result);
                    }
                }

                functionResponses.push({
                    name: call.name,
                    response: { result },
                    id: call.id
                });
            }

            // Send tool responses back to model
            responseStream = await session.sendMessageStream({
                parts: [{ functionResponse: { functionResponses: functionResponses } }]
            } as any);
        } else {
            // No more tool calls, we are done
            break;
        }
    }

  } catch (error) {
    console.error("Gemini Chat Error:", error);
    throw error;
  }
}

// --- Live API (Voice) Service ---

export interface LiveSessionCallbacks {
  onOpen: () => void;
  onMessage: (text: string | null, audioBuffer: AudioBuffer | null, isInterrupted: boolean) => void;
  onAudioData: (data: Uint8Array) => void; // For visualizer
  onError: (error: Error) => void;
  onClose: () => void;
  onToolCall: (toolName: string) => void;
  onToolSuccess?: (toolName: string, result: any) => void;
}

export const connectLiveSession = async (callbacks: LiveSessionCallbacks, emergencyMode: boolean = false, language: Language = 'en') => {
  let ai;
  try {
    ai = getAIClient();
  } catch (error) {
    callbacks.onError(new Error("API_KEY_MISSING"));
    return null;
  }

  const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
  const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

  // Audio Analysis for Visualizer
  const analyser = outputAudioContext.createAnalyser();
  analyser.fftSize = 64; 
  const dataArray = new Uint8Array(analyser.frequencyBinCount);

  // Connect analyser only once to the destination to avoid graph topology errors
  analyser.connect(outputAudioContext.destination);

  const visualizerInterval = setInterval(() => {
    analyser.getByteFrequencyData(dataArray);
    let sum = 0;
    for(let i=0; i<dataArray.length; i++) sum += dataArray[i];
    if (sum > 0) {
      callbacks.onAudioData(new Uint8Array(dataArray));
    } else {
        callbacks.onAudioData(new Uint8Array(dataArray.fill(0)));
    }
  }, 50);

  let nextStartTime = 0;
  const sources = new Set<AudioBufferSourceNode>();

  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch (err: any) {
    console.error("Microphone access denied:", err);
    clearInterval(visualizerInterval);
    if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
      callbacks.onError(new Error("MIC_PERMISSION_DENIED"));
    } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
      callbacks.onError(new Error("MIC_NOT_FOUND"));
    } else {
      callbacks.onError(new Error("MIC_UNKNOWN_ERROR"));
    }
    return null;
  }

  // Ensure AudioContexts are running (fixes Autoplay policy issues)
  await inputAudioContext.resume();
  await outputAudioContext.resume();

  let instructions = getSystemInstruction(language);
  if (emergencyMode) {
    instructions += "\n\n[SYSTEM OVERRIDE: EMERGENCY MODE ACTIVE]. Respond concisely. Prioritize safety protocols immediately.";
  }

  const sessionPromise = ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-09-2025',
    callbacks: {
      onopen: () => {
        callbacks.onOpen();

        const source = inputAudioContext.createMediaStreamSource(stream);
        const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

        scriptProcessor.onaudioprocess = async (audioProcessingEvent) => {
          const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
          const pcmBlob = createBlob(inputData);
          const base64Data = await blobToBase64(pcmBlob);

          sessionPromise.then((session) => {
            session.sendRealtimeInput({
               media: {
                 mimeType: 'audio/pcm;rate=16000',
                 data: base64Data
               }
            });
          });
        };

        source.connect(scriptProcessor);
        scriptProcessor.connect(inputAudioContext.destination);
      },
      onmessage: async (message: LiveServerMessage) => {
        // Tool Handling
        if (message.toolCall) {
            console.log("Tool Call received:", message.toolCall);
            for (const fc of message.toolCall.functionCalls) {
                callbacks.onToolCall(fc.name);

                let result = {};
                if (fc.name === 'book_appointment') {
                    result = await mockBookAppointment(fc.args);
                    if ((result as any).status === 'success') {
                        callbacks.onToolSuccess?.(fc.name, result);
                    }
                } else if (fc.name === 'log_to_crm') {
                    result = await mockLogToCRM(fc.args);
                    if ((result as any).status === 'logged') {
                        callbacks.onToolSuccess?.(fc.name, result);
                    }
                }

                sessionPromise.then(session => {
                    session.sendToolResponse({
                        functionResponses: {
                            id: fc.id,
                            name: fc.name,
                            response: { result }
                        }
                    });
                });
            }
        }

        // Audio Handling
        const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
        let audioBuffer: AudioBuffer | null = null;

        if (base64Audio) {
          try {
            nextStartTime = Math.max(nextStartTime, outputAudioContext.currentTime);
            audioBuffer = await decodeAudioData(
              base64ToUint8Array(base64Audio),
              outputAudioContext,
              24000,
              1
            );

            const source = outputAudioContext.createBufferSource();
            source.buffer = audioBuffer;
            // Connect to analyser, which is already connected to destination
            source.connect(analyser); 

            source.addEventListener('ended', () => {
              sources.delete(source);
            });

            source.start(nextStartTime);
            nextStartTime += audioBuffer.duration;
            sources.add(source);
          } catch (e) {
            console.error("Error decoding audio", e);
          }
        }

        const interrupted = message.serverContent?.interrupted;
        if (interrupted) {
          for (const src of sources.values()) {
            src.stop();
            sources.delete(src);
          }
          nextStartTime = 0;
        }

        callbacks.onMessage(null, audioBuffer, !!interrupted);
      },
      onerror: (e) => {
        console.error("Gemini Live API Error:", e);
        callbacks.onError(new Error("CONNECTION_ERROR"));
      },
      onclose: () => {
        callbacks.onClose();
        clearInterval(visualizerInterval);
      }
    },
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
      },
      systemInstruction: instructions,
      tools: [{ functionDeclarations: TOOLS }]
    }
  });

  return {
    disconnect: async () => {
      clearInterval(visualizerInterval);
      try {
        const session = await sessionPromise;
        session.close();
      } catch (e) {
        console.warn("Session close error", e);
      }

      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }

      if (inputAudioContext.state !== 'closed') inputAudioContext.close();
      if (outputAudioContext.state !== 'closed') outputAudioContext.close();
    }
  };
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, QuickAction, Language } from '../types';
import { sendMessageToGemini } from '../services/geminiService';
import { Send, Bot, User, Loader2, Box, DollarSign, Hammer, BookOpen, AlertTriangle, CheckCircle2 } from 'lucide-react';
import { GenerateContentResponse } from '@google/genai';
import { UI_TRANSLATIONS } from '../constants';

interface ChatTabProps {
  quickActions: QuickAction[];
  initialMessage?: string;
  emergencyMode?: boolean;
  language: Language;
}

const ChatTab: React.FC<ChatTabProps> = ({ quickActions, initialMessage, emergencyMode, language }) => {
  const t = UI_TRANSLATIONS[language];

  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      text: t.chatWelcome,
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showBookingConfirmation, setShowBookingConfirmation] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const hasProcessedInitial = useRef(false);

  // Update welcome message when language changes, but only if it's the only message
  useEffect(() => {
    if (messages.length === 1 && messages[0].id === 'welcome') {
        setMessages([{
            id: 'welcome',
            role: 'model',
            text: t.chatWelcome,
            timestamp: new Date()
        }]);
    }
  }, [language, t.chatWelcome]);

  // Check for API Key on mount
  useEffect(() => {
    if (!process.env.API_KEY) {
      setError("System Error: API Key is missing. Please contact support.");
    }
  }, []);

  useEffect(() => {
    if (initialMessage && !hasProcessedInitial.current && !isLoading && !error) {
      hasProcessedInitial.current = true;
      handleSendMessage(initialMessage);
    }
  }, [initialMessage]);

  useEffect(() => {
    if (showBookingConfirmation) {
        const timer = setTimeout(() => setShowBookingConfirmation(false), 5000);
        return () => clearTimeout(timer);
    }
  }, [showBookingConfirmation]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async (text: string) => {
    if (!text.trim() || isLoading) return;

    // Clear previous errors
    setError(null);

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      const responseGenerator = sendMessageToGemini(
          text, 
          emergencyMode, 
          language,
          (toolName, result) => {
              if (toolName === 'book_appointment') {
                  setShowBookingConfirmation(true);
              }
          }
      );

      const botMsgId = (Date.now() + 1).toString();
      setMessages(prev => [...prev, {
        id: botMsgId,
        role: 'model',
        text: '', // Start empty
        timestamp: new Date()
      }]);

      let fullText = '';

      for await (const chunk of responseGenerator) {
        const c = chunk as GenerateContentResponse;
        const chunkText = c.text || '';
        fullText += chunkText;

        setMessages(prev => prev.map(msg => 
          msg.id === botMsgId ? { ...msg, text: fullText } : msg
        ));
      }
    } catch (error: any) {
      console.error("Chat error:", error);
      let errorMsg = language === 'en' ? "I'm having trouble connecting. Please try again." : "Tengo problemas de conexión. Inténtalo de nuevo.";

      if (error.message?.includes("API_KEY_MISSING")) {
        errorMsg = language === 'en' ? "Configuration Error: API Key is missing." : "Error de Configuración: Falta la API Key.";
      }

      setError(errorMsg);

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
