            <p className="text-sm text-gray-500 text-center mb-4">Enter Administrator PIN to access system controls and CRM logs.</p>
            <input
              type="password"
              value={pin}
              onChange={(e) => { setPin(e.target.value); setLoginError(''); }}
              onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
