                      </div>
                      <p className="text-gray-600 mb-2 text-xs leading-relaxed">{log.summary}</p>
                      <div className="flex items-center gap-1 text-[10px] text-brand-600 bg-brand-50 px-2 py-1 rounded w-fit">
                        <Database size={10} />
