              </div>
            </div>

            <button 
              onClick={() => setIsAuthenticated(false)} 
              className="w-full text-gray-500 text-sm font-medium py-2 hover:bg-gray-100 rounded-lg transition-colors border border-gray-200"
            >
              Lock Dashboard
            </button>
          </div>
        )}
