  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import ChatTab from './components/ChatTab';
import CallTab from './components/CallTab';
import ServicesTab from './components/ServicesTab';
import InfoTab from './components/InfoTab';
import AdminDashboard from './components/AdminDashboard';
import { Tab, Language, VoiceName } from './types';
import { BUSINESS_CONFIG, QUICK_ACTIONS, SERVICES } from './constants';
import { resetChatSession } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.CHAT);
  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
  const [emergencyMode, setEmergencyMode] = useState(false);
  const [language, setLanguage] = useState<Language>('en');
  const [voiceName, setVoiceName] = useState<VoiceName>('Kore');
  const [initialMessage, setInitialMessage] = useState<string | undefined>(undefined);

  // Reset chat session when settings change to ensure new context/language is used
  useEffect(() => {
    resetChatSession();
  }, [emergencyMode, language]);

  const handleConsultProduct = (productName: string) => {
    const msg = language === 'en' 
        ? `Tell me more about ${productName}` 
        : `Cuéntame más sobre ${productName}`;
    setInitialMessage(msg);
    setActiveTab(Tab.CHAT);
  };

  const renderContent = () => {
    switch (activeTab) {
      case Tab.CHAT:
        return <ChatTab 
            quickActions={QUICK_ACTIONS} 
            emergencyMode={emergencyMode} 
            language={language}
            initialMessage={initialMessage}
        />;
      case Tab.CALL:
        return <CallTab 
            emergencyMode={emergencyMode} 
            language={language}
            voiceName={voiceName}
        />;
      case Tab.SERVICES:
        return <ServicesTab 
            services={SERVICES} 
            language={language} 
            onConsultProduct={handleConsultProduct}
        />;
      case Tab.INFO:
        return <InfoTab 
            config={BUSINESS_CONFIG} 
            language={language}
        />;
      default:
        return <ChatTab 
            quickActions={QUICK_ACTIONS} 
            emergencyMode={emergencyMode} 
            language={language}
        />;
    }
  };

  return (
    <>
        <Layout 
        activeTab={activeTab} 
        onTabChange={setActiveTab}
        config={BUSINESS_CONFIG}
        onOpenDashboard={() => setIsDashboardOpen(true)}
        language={language}
        setLanguage={setLanguage}
        >
        {renderContent()}
        </Layout>

        <AdminDashboard 
            isOpen={isDashboardOpen} 
            onClose={() => setIsDashboardOpen(false)} 
            emergencyMode={emergencyMode}
            setEmergencyMode={setEmergencyMode}
            voiceName={voiceName}
            setVoiceName={setVoiceName}
        />
    </>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Mic, Phone, AlertCircle, CalendarCheck, Database, Loader2, CheckCircle2 } from 'lucide-react';
import { connectLiveSession } from '../services/geminiService';
import AudioVisualizer from './AudioVisualizer';
import { Language, VoiceName } from '../types';
import { UI_TRANSLATIONS } from '../constants';

interface CallTabProps {
  emergencyMode?: boolean;
  language: Language;
  voiceName: VoiceName;
}

const CallTab: React.FC<CallTabProps> = ({ emergencyMode, language, voiceName }) => {
  const t = UI_TRANSLATIONS[language];

  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [audioData, setAudioData] = useState<Uint8Array>(new Uint8Array(64));
  const [activeTool, setActiveTool] = useState<string | null>(null);
  const [showBookingConfirmation, setShowBookingConfirmation] = useState(false);

  const disconnectRef = useRef<(() => Promise<void>) | null>(null);

  useEffect(() => {
    return () => {
      if (disconnectRef.current) {
        disconnectRef.current();
      }
    };
  }, []);

  // Clear tool status after delay
  useEffect(() => {
    if (activeTool) {
      const timer = setTimeout(() => setActiveTool(null), 3500);
      return () => clearTimeout(timer);
    }
  }, [activeTool]);

  useEffect(() => {
    if (showBookingConfirmation) {
        const timer = setTimeout(() => setShowBookingConfirmation(false), 5000);
        return () => clearTimeout(timer);
    }
  }, [showBookingConfirmation]);

  const mapErrorToUserMessage = (error: Error): string => {
    const msg = error.message;
    if (language === 'en') {
        if (msg.includes("API_KEY_MISSING")) return "Configuration Error: API Key missing.";
        if (msg.includes("MIC_PERMISSION_DENIED")) return "Microphone access denied. Please check settings.";
        if (msg.includes("MIC_NOT_FOUND")) return "No microphone detected.";
        if (msg.includes("CONNECTION_ERROR")) return "Network connection interrupted.";
        return "An unexpected error occurred.";
    } else {
        if (msg.includes("API_KEY_MISSING")) return "Error de Configuración: Falta API Key.";
        if (msg.includes("MIC_PERMISSION_DENIED")) return "Acceso al micrófono denegado.";
        if (msg.includes("MIC_NOT_FOUND")) return "Micrófono no encontrado.";
        if (msg.includes("CONNECTION_ERROR")) return "Conexión interrumpida.";
        return "Ocurrió un error inesperado.";
    }
  };

  const handleStartCall = async () => {
    setStatus('connecting');
    setErrorMessage('');

    try {
      const session = await connectLiveSession({
        onOpen: () => {
          setStatus('connected');
        },
        onMessage: (text, audioBuffer, interrupted) => {
           // handled by service
        },
        onAudioData: (data) => {
            setAudioData(data);
        },
        onToolCall: (toolName) => {
            setActiveTool(toolName);
        },
        onToolSuccess: (toolName, result) => {
             if (toolName === 'book_appointment') {
                 setShowBookingConfirmation(true);
             }
        },
        onError: (err) => {
          console.error("Live Session Error:", err);
          setErrorMessage(mapErrorToUserMessage(err));
          setStatus('error');
        },
        onClose: () => {
          setStatus('idle');
        }
      }, emergencyMode, language, voiceName);

      if (!session) {
        return;
      }

      disconnectRef.current = session.disconnect;

    } catch (e: any) {
      console.error(e);
      setErrorMessage(mapErrorToUserMessage(e));
      setStatus('error');
    }
  };

  const handleEndCall = async () => {
    if (disconnectRef.current) {
      await disconnectRef.current();
      disconnectRef.current = null;
    }
    setStatus('idle');
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 relative overflow-hidden font-sans">

      {/* Top Status Area - Clean & Minimal */}
      <div className="pt-10 pb-4 text-center z-10 px-6 transition-opacity duration-300">
        <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">{t.voiceTitle}</h2>
        <div className={`text-xl font-light tracking-tight transition-colors duration-300 ${
            status === 'error' ? 'text-red-600' : 
            status === 'connected' ? 'text-slate-800' : 'text-slate-500'
        }`}>
          {status === 'idle' && t.tapToStart}
          {status === 'connecting' && (
              <span className="animate-pulse">{t.connecting}</span>
          )}
          {status === 'connected' && t.connected}
          {status === 'error' && t.connectionFailed}
        </div>
      </div>

      {/* Visualizer / Centerpiece */}
      <div className="flex-1 relative flex flex-col items-center justify-center min-h-[300px]">

        {/* Success Banner Overlay - Positioned near top of visualizer area */}
        <div className={`absolute top-0 z-40 transition-all duration-500 transform w-full px-6 flex justify-center ${
            showBookingConfirmation ? 'translate-y-12 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'
        }`}>
            <div className="bg-emerald-500/90 backdrop-blur text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3">
                <div className="bg-white/20 p-1 rounded-full">
                    <CheckCircle2 size={18} className="text-white" />
                </div>
                <p className="text-xs font-bold tracking-wide">{t.bookingConfirmed}</p>
            </div>
        </div>

        {/* Pro Tool Status Indicator - Sleek Badge */}
        <div className={`absolute top-0 z-30 transition-all duration-500 ease-out transform ${
            activeTool && !showBookingConfirmation ? 'translate-y-2 opacity-100' : '-translate-y-4 opacity-0'
        }`}>
            <div className="bg-slate-900/95 backdrop-blur-sm text-white px-5 py-2.5 rounded-full shadow-2xl flex items-center gap-3 border border-slate-700/50">
                {activeTool === 'book_appointment' ? (
                    <CalendarCheck size={14} className="text-emerald-400" />
                ) : activeTool === 'log_to_crm' ? (
                    <Database size={14} className="text-sky-400" />
                ) : (
                    <Loader2 size={14} className="text-slate-400 animate-spin" />
                )}

                <div className="flex flex-col leading-none">
                    <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">System Action</span>
                    <span className="text-xs font-semibold tracking-wide">
                        {activeTool === 'book_appointment' ? 'Syncing Calendar' : 
                         activeTool === 'log_to_crm' ? 'Updating CRM' : 'Processing...'}
                    </span>
                </div>
            </div>
        </div>

        <div className="relative z-10 w-full flex flex-col items-center justify-center space-y-12">
            {/* The Visualizer */}
            <div className={`h-[100px] w-full flex items-center justify-center px-8 transition-opacity duration-500 ${activeTool ? 'opacity-30' : 'opacity-100'}`}>
                <AudioVisualizer audioData={audioData} isActive={status === 'connected'} />
            </div>

            {/* Mic Button with Contextual Ring Animation */}
            <div className="relative group">
                {/* Active Tool Pulse Ring */}
                {activeTool && (
                    <div className="absolute inset-0 rounded-full border border-sky-400/30 animate-ping" />
                )}

                <div 
                    onClick={status === 'idle' ? handleStartCall : undefined}
                    className={`relative w-20 h-20 rounded-full flex items-center justify-center transition-all duration-500 shadow-xl ${
                    status === 'connected' 
                        ? activeTool 
                            ? 'bg-slate-900 scale-100 ring-2 ring-sky-500/50' // Tool active state
                            : 'bg-white scale-110 ring-1 ring-slate-200'    // Normal listening state
                        : status === 'error' 
                        ? 'bg-red-50 border-2 border-red-200'
                        : 'bg-slate-900 cursor-pointer hover:scale-105 hover:shadow-2xl'
                    }`}
                >
                    {status === 'connected' ? (
                        activeTool ? (
                             <Loader2 size={24} className="text-sky-400 animate-spin" />
                        ) : (
                             <div className="relative">
                                 <div className="absolute inset-0 bg-brand-500 blur-lg opacity-20 animate-pulse"></div>
                                 <Mic size={24} className="text-brand-600 relative z-10" />
                             </div>
                        )
                    ) : status === 'error' ? (
                        <AlertCircle size={24} className="text-red-500" />
                    ) : status === 'connecting' ? (
                         <Loader2 size={24} className="text-white animate-spin" />
                    ) : (
                        <Mic size={24} className="text-white" />
                    )}
                </div>
            </div>
        </div>
      </div>

      {/* Controls Area */}
      <div className="w-full p-8 pt-0 space-y-6 shrink-0 z-10">

        {/* Suggestions - Subtle fade out when connected */}
        <div className={`transition-all duration-500 ${status === 'idle' ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none hidden'}`}>
            <p className="text-[10px] text-center text-slate-400 font-bold uppercase tracking-widest mb-3">{t.tryAsking}</p>
            <div className="grid grid-cols-1 gap-2">
              {t.suggestions.slice(0, 3).map((s, i) => (
                <button 
                  key={i} 
                  className="bg-white border border-slate-200 p-3 rounded-lg text-sm text-slate-600 text-center shadow-sm hover:border-brand-300 hover:text-brand-700 transition-all"
                  onClick={handleStartCall} // Optional: click suggestion to start
                >
                  "{s}"
                </button>
              ))}
            </div>
        </div>

        {status === 'error' && (
          <div className="bg-red-50/50 backdrop-blur border border-red-100 text-red-700 text-sm p-4 rounded-xl text-center">
            <p className="font-medium mb-2">{errorMessage}</p>
            <button 
                onClick={() => setStatus('idle')}
                className="text-xs font-bold uppercase tracking-wide text-red-800 hover:text-red-950 border-b border-red-300 pb-0.5"
            >
                Reset Connection
            </button>
          </div>
        )}

        {status === 'idle' && (
          <button 
            onClick={handleStartCall}
            className="w-full bg-slate-900 text-white font-medium text-sm tracking-wide uppercase py-4 rounded-xl shadow-lg hover:bg-slate-800 transition-transform active:scale-[0.98]"
          >
            {t.startConversation}
          </button>
        )}

        {/* End Call Button - Only visible when connected */}
        {status === 'connected' && (
          <div className="flex justify-center pt-4">
            <button 
              onClick={handleEndCall}
              className="group flex items-center gap-2 px-6 py-3 bg-red-50 text-red-600 rounded-full hover:bg-red-100 transition-colors"
            >
              <Phone size={18} className="rotate-[135deg]" />
              <span className="text-xs font-bold uppercase tracking-widest">{t.endCall}</span>
            </button>
          </div>
        )}

        {status !== 'idle' && status !== 'error' && (
          <p className="text-[10px] text-center text-slate-300 font-medium tracking-widest uppercase mt-4">
            {t.secureConnection}
          </p>
        )}
      </div>
    </div>
  );
};

