  } catch (error) {
    console.error("CRM Log failed:", error);
    return { status: "error", message: "Failed to log interaction" };
  }
};

// --- Chat Service ---

let chatSession: Chat | null = null;
let currentLanguage: Language = 'en';

// Helper to reset session if needed (e.g. emergency mode toggle or language change)
export const resetChatSession = () => {
  chatSession = null;
};

export const getChatSession = (emergencyMode: boolean = false, language: Language = 'en') => {
  if (!chatSession || currentLanguage !== language) {
    const ai = getAIClient();
    let instructions = getSystemInstruction(language);
    currentLanguage = language;

    if (emergencyMode) {
      instructions += "\n\n[SYSTEM OVERRIDE: EMERGENCY MODE ACTIVE]. Respond concisely. Prioritize safety protocols immediately.";
    }

    chatSession = ai.chats.create({
      model: 'gemini-2.5-flash',
      config: {
        systemInstruction: instructions,
        tools: [{ functionDeclarations: TOOLS }],
      },
    });
  }
  return chatSession;
};

export async function* sendMessageToGemini(
  message: string, 
  emergencyMode: boolean = false, 
  language: Language = 'en',
  onToolSuccess?: (toolName: string, result: any) => void
) {
  try {
    const session = getChatSession(emergencyMode, language);
    let responseStream = await session.sendMessageStream({ message });

    while (true) {
        let toolCalls: FunctionCall[] = [];

        for await (const chunk of responseStream) {
            // Check for tool calls
            const fc = chunk.functionCalls;
            if (fc && fc.length > 0) {
                toolCalls.push(...fc);
            }

            // Yield text content if present
            if (chunk.text) {
                yield chunk;
            }
        }

        if (toolCalls.length > 0) {
            const functionResponses = [];
            for (const call of toolCalls) {
                let result = {};
                if (call.name === 'book_appointment') {
                    result = await mockBookAppointment(call.args);
                    if ((result as any).status === 'success') {
                        onToolSuccess?.(call.name, result);
                    }
                } else if (call.name === 'log_to_crm') {
                    result = await mockLogToCRM(call.args);
                    if ((result as any).status === 'logged') {
                        onToolSuccess?.(call.name, result);
                    }
                }

                functionResponses.push({
                    name: call.name,
                    response: { result },
                    id: call.id
                });
            }

            // Send tool responses back to model
            responseStream = await session.sendMessageStream({
                parts: [{ functionResponse: { functionResponses: functionResponses } }]
            } as any);
        } else {
            // No more tool calls, we are done
            break;
        }
    }

  } catch (error) {
    console.error("Gemini Chat Error:", error);
    throw error;
  }
}

// --- Live API (Voice) Service ---

export interface LiveSessionCallbacks {
  onOpen: () => void;
  onMessage: (text: string | null, audioBuffer: AudioBuffer | null, isInterrupted: boolean) => void;
  onAudioData: (data: Uint8Array) => void; // For visualizer
  onError: (error: Error) => void;
  onClose: () => void;
  onToolCall: (toolName: string) => void;
  onToolSuccess?: (toolName: string, result: any) => void;
}

export const connectLiveSession = async (
    callbacks: LiveSessionCallbacks, 
    emergencyMode: boolean = false, 
    language: Language = 'en',
    voiceName: VoiceName = 'Kore'
) => {
  let ai;
  try {
    ai = getAIClient();
  } catch (error) {
    callbacks.onError(new Error("API_KEY_MISSING"));
    return null;
  }

  const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
  const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

  // Audio Analysis for Visualizer
  const analyser = outputAudioContext.createAnalyser();
  analyser.fftSize = 64; 
  const dataArray = new Uint8Array(analyser.frequencyBinCount);

  // Connect analyser only once to the destination to avoid graph topology errors
  analyser.connect(outputAudioContext.destination);

  const visualizerInterval = setInterval(() => {
    analyser.getByteFrequencyData(dataArray);
    let sum = 0;
    for(let i=0; i<dataArray.length; i++) sum += dataArray[i];
    if (sum > 0) {
      callbacks.onAudioData(new Uint8Array(dataArray));
    } else {
        callbacks.onAudioData(new Uint8Array(dataArray.fill(0)));
    }
  }, 50);

  let nextStartTime = 0;
  const sources = new Set<AudioBufferSourceNode>();

  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch (err: any) {
    console.error("Microphone access denied:", err);
    clearInterval(visualizerInterval);
    if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
      callbacks.onError(new Error("MIC_PERMISSION_DENIED"));
    } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
      callbacks.onError(new Error("MIC_NOT_FOUND"));
    } else {
      callbacks.onError(new Error("MIC_UNKNOWN_ERROR"));
    }
    return null;
  }

  // Ensure AudioContexts are running (fixes Autoplay policy issues)
  await inputAudioContext.resume();
  await outputAudioContext.resume();

  let instructions = getSystemInstruction(language);
  if (emergencyMode) {
    instructions += "\n\n[SYSTEM OVERRIDE: EMERGENCY MODE ACTIVE]. Respond concisely. Prioritize safety protocols immediately.";
  }

  const sessionPromise = ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-09-2025',
    callbacks: {
      onopen: () => {
        callbacks.onOpen();

        const source = inputAudioContext.createMediaStreamSource(stream);
        const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

        scriptProcessor.onaudioprocess = async (audioProcessingEvent) => {
          const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
          const pcmBlob = createBlob(inputData);
          const base64Data = await blobToBase64(pcmBlob);

          sessionPromise.then((session) => {
            session.sendRealtimeInput({
               media: {
                 mimeType: 'audio/pcm;rate=16000',
                 data: base64Data
               }
            });
          });
        };

        source.connect(scriptProcessor);
        scriptProcessor.connect(inputAudioContext.destination);
      },
      onmessage: async (message: LiveServerMessage) => {
        // Tool Handling
        if (message.toolCall) {
            console.log("Tool Call received:", message.toolCall);
            for (const fc of message.toolCall.functionCalls) {
                callbacks.onToolCall(fc.name);

                let result = {};
                if (fc.name === 'book_appointment') {
                    result = await mockBookAppointment(fc.args);
                    if ((result as any).status === 'success') {
                        callbacks.onToolSuccess?.(fc.name, result);
                    }
                } else if (fc.name === 'log_to_crm') {
                    result = await mockLogToCRM(fc.args);
                    if ((result as any).status === 'logged') {
                        callbacks.onToolSuccess?.(fc.name, result);
                    }
                }

                sessionPromise.then(session => {
                    session.sendToolResponse({
                        functionResponses: {
                            id: fc.id,
                            name: fc.name,
                            response: { result }
                        }
                    });
                });
            }
        }

        // Audio Handling
        const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
        let audioBuffer: AudioBuffer | null = null;

        if (base64Audio) {
          try {
            nextStartTime = Math.max(nextStartTime, outputAudioContext.currentTime);
            audioBuffer = await decodeAudioData(
              base64ToUint8Array(base64Audio),
              outputAudioContext,
              24000,
              1
            );

            const source = outputAudioContext.createBufferSource();
            source.buffer = audioBuffer;
            // Connect to analyser, which is already connected to destination
            source.connect(analyser); 

            source.addEventListener('ended', () => {
              sources.delete(source);
            });

            source.start(nextStartTime);
            nextStartTime += audioBuffer.duration;
            sources.add(source);
          } catch (e) {
            console.error("Error decoding audio", e);
          }
        }

        const interrupted = message.serverContent?.interrupted;
        if (interrupted) {
          for (const src of sources.values()) {
            src.stop();
            sources.delete(src);
          }
          nextStartTime = 0;
        }

        callbacks.onMessage(null, audioBuffer, !!interrupted);
      },
      onerror: (e) => {
        console.error("Gemini Live API Error:", e);
        callbacks.onError(new Error("CONNECTION_ERROR"));
      },
      onclose: () => {
        callbacks.onClose();
        clearInterval(visualizerInterval);
      }
    },
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceName } }
      },
      systemInstruction: instructions,
      tools: [{ functionDeclarations: TOOLS }]
    }
  });

  return {
    disconnect: async () => {
      clearInterval(visualizerInterval);
      try {
        const session = await sessionPromise;
        session.close();
      } catch (e) {
        console.warn("Session close error", e);
      }

      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }

      if (inputAudioContext.state !== 'closed') inputAudioContext.close();
      if (outputAudioContext.state !== 'closed') outputAudioContext.close();
    }
  };
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, QuickAction, Language } from '../types';
import { sendMessageToGemini } from '../services/geminiService';
import { Send, Bot, User, Loader2, Box, DollarSign, Hammer, BookOpen, AlertTriangle, CheckCircle2 } from 'lucide-react';
import { GenerateContentResponse } from '@google/genai';
import { UI_TRANSLATIONS } from '../constants';

interface ChatTabProps {
  quickActions: QuickAction[];
  initialMessage?: string;
  emergencyMode?: boolean;
  language: Language;
}

const ChatTab: React.FC<ChatTabProps> = ({ quickActions, initialMessage, emergencyMode, language }) => {
  const t = UI_TRANSLATIONS[language];

  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      text: t.chatWelcome,
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [showBookingConfirmation, setShowBookingConfirmation] = useState(false);
  const [confirmedDate, setConfirmedDate] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const hasProcessedInitial = useRef(false);

  // Update welcome message when language changes, but only if it's the only message
  useEffect(() => {
    if (messages.length === 1 && messages[0].id === 'welcome') {
        setMessages([{
            id: 'welcome',
            role: 'model',
            text: t.chatWelcome,
            timestamp: new Date()
        }]);
    }
  }, [language, t.chatWelcome]);

  // Check for API Key on mount
  useEffect(() => {
    if (!process.env.API_KEY) {
      setError("System Error: API Key is missing. Please contact support.");
    }
  }, []);

  useEffect(() => {
    if (initialMessage && !hasProcessedInitial.current && !isLoading && !error) {
      hasProcessedInitial.current = true;
      handleSendMessage(initialMessage);
    }
  }, [initialMessage]);

  useEffect(() => {
    if (showBookingConfirmation) {
        const timer = setTimeout(() => setShowBookingConfirmation(false), 5000);
        return () => clearTimeout(timer);
    }
  }, [showBookingConfirmation]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async (text: string) => {
    if (!text.trim() || isLoading) return;

    // Clear previous errors
    setError(null);

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      const responseGenerator = sendMessageToGemini(
          text, 
          emergencyMode, 
          language,
          (toolName, result) => {
              if (toolName === 'book_appointment') {
                  setConfirmedDate(result.date || null);
                  setShowBookingConfirmation(true);
              }
          }
      );

      const botMsgId = (Date.now() + 1).toString();
      setMessages(prev => [...prev, {
        id: botMsgId,
        role: 'model',
        text: '', // Start empty
        timestamp: new Date()
      }]);

      let fullText = '';

      for await (const chunk of responseGenerator) {
        const c = chunk as GenerateContentResponse;
        const chunkText = c.text || '';
        fullText += chunkText;

        setMessages(prev => prev.map(msg => 
          msg.id === botMsgId ? { ...msg, text: fullText } : msg
        ));
      }
    } catch (error: any) {
      console.error("Chat error:", error);
      let errorMsg = language === 'en' ? "I'm having trouble connecting. Please try again." : "Tengo problemas de conexión. Inténtalo de nuevo.";

      if (error.message?.includes("API_KEY_MISSING")) {
        errorMsg = language === 'en' ? "Configuration Error: API Key is missing." : "Error de Configuración: Falta la API Key.";
      }

      setError(errorMsg);

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: language === 'en' ? "⚠️ Connection interrupted. Please check your internet." : "⚠️ Conexión interrumpida. Revisa tu internet.",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const getIcon = (name: string) => {
    switch(name) {
      case 'Box': return <Box size={16} />;
      case 'DollarSign': return <DollarSign size={16} />;
      case 'Hammer': return <Hammer size={16} />;
      case 'BookOpen': return <BookOpen size={16} />;
      default: return <Box size={16} />;
    }
  };

  return (
    <div className="flex flex-col h-full relative">

      {/* Success Banner Overlay */}
      <div className={`absolute top-4 left-4 right-4 z-50 transition-all duration-500 transform ${showBookingConfirmation ? 'translate-y-0 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'}`}>
        <div className="bg-emerald-50 border border-emerald-200 text-emerald-800 p-4 rounded-xl shadow-lg flex items-center gap-3">
            <div className="bg-emerald-100 p-2 rounded-full text-emerald-600">
                <CheckCircle2 size={24} />
            </div>
            <div>
                <p className="font-bold text-sm">Success</p>
                <p className="text-xs">{t.bookingConfirmed}</p>
                {confirmedDate && (
                  <p className="text-xs font-bold mt-1 text-emerald-700">{confirmedDate}</p>
                )}
            </div>
        </div>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6 no-scrollbar relative">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`flex max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-end gap-2`}>
              <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${
                msg.role === 'user' ? 'bg-brand-500 text-white' : 'bg-brand-900 text-accent-500'
              }`}>
                {msg.role === 'user' ? <User size={16} /> : <Bot size={16} />}
              </div>
              <div 
                className={`p-3.5 rounded-2xl text-sm leading-relaxed shadow-sm ${
                  msg.role === 'user' 
                    ? 'bg-brand-500 text-white rounded-br-none' 
                    : 'bg-white text-gray-800 rounded-bl-none border border-gray-100'
                }`}
              >
                 {msg.text.split('\n').map((line, i) => (
                    <p key={i} className={i > 0 ? 'mt-2' : ''}>{line}</p>
                 ))}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
             <div className="flex max-w-[85%] items-end gap-2">
                <div className="w-8 h-8 rounded-full bg-brand-900 text-accent-500 flex items-center justify-center shrink-0">
                  <Bot size={16} />
                </div>
                <div className="bg-white p-3 rounded-2xl rounded-bl-none border border-gray-100 shadow-sm">
                  <Loader2 className="animate-spin text-brand-500" size={18} />
                </div>
             </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Error Banner */}
      {error && (
        <div className="px-4 pb-2">
          <div className="bg-red-50 border border-red-100 text-red-700 px-3 py-2 rounded-lg text-xs flex items-center gap-2">
            <AlertTriangle size={14} />
            <span>{error}</span>
          </div>
        </div>
      )}

      {/* Quick Actions */}
      <div className="px-4 py-2">
         <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
            {quickActions.map(action => (
              <button
                key={action.id}
                onClick={() => handleSendMessage(action.message)}
                disabled={isLoading || !!error}
                className="flex items-center gap-2 whitespace-nowrap bg-white border border-brand-100 px-3 py-2 rounded-full text-xs font-medium text-brand-700 hover:bg-brand-50 hover:border-brand-300 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {getIcon(action.iconName)}
                {action.title}
              </button>
            ))}
         </div>
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t border-gray-100">
        <div className={`flex items-center gap-2 bg-gray-50 p-2 rounded-xl border transition-all ${
          error ? 'border-red-200' : 'border-gray-200 focus-within:border-brand-500 focus-within:ring-1 focus-within:ring-brand-500'
        }`}>
          <input
            type="text"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage(inputText)}
            placeholder={error ? (language === 'en' ? "Chat disabled" : "Chat deshabilitado") : t.chatPlaceholder}
            className="flex-1 bg-transparent border-none outline-none text-sm px-2 text-gray-800 placeholder-gray-400 disabled:text-gray-400"
            disabled={isLoading || !!error}
          />
          <button 
            onClick={() => handleSendMessage(inputText)}
            disabled={!inputText.trim() || isLoading || !!error}
            className={`p-2 rounded-lg transition-colors ${
              inputText.trim() && !isLoading && !error
                ? 'bg-brand-600 text-white hover:bg-brand-700 shadow-md' 
                : 'bg-gray-200 text-gray-400 cursor-not-allowed'
            }`}
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatTab;

import React, { useState, useEffect, useRef } from 'react';
import { Mic, Phone, AlertCircle, CalendarCheck, Database, Loader2, CheckCircle2 } from 'lucide-react';
import { connectLiveSession } from '../services/geminiService';
import AudioVisualizer from './AudioVisualizer';
import { Language, VoiceName } from '../types';
import { UI_TRANSLATIONS } from '../constants';

interface CallTabProps {
  emergencyMode?: boolean;
  language: Language;
  voiceName: VoiceName;
}

const CallTab: React.FC<CallTabProps> = ({ emergencyMode, language, voiceName }) => {
  const t = UI_TRANSLATIONS[language];

  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [audioData, setAudioData] = useState<Uint8Array>(new Uint8Array(64));
  const [activeTool, setActiveTool] = useState<string | null>(null);

  const [showBookingConfirmation, setShowBookingConfirmation] = useState(false);
  const [confirmedDate, setConfirmedDate] = useState<string | null>(null);

  const disconnectRef = useRef<(() => Promise<void>) | null>(null);

  useEffect(() => {
    return () => {
      if (disconnectRef.current) {
        disconnectRef.current();
      }
    };
  }, []);

  // Clear tool status after delay
  useEffect(() => {
    if (activeTool) {
      const timer = setTimeout(() => setActiveTool(null), 3500);
      return () => clearTimeout(timer);
    }
  }, [activeTool]);

  useEffect(() => {
    if (showBookingConfirmation) {
        const timer = setTimeout(() => setShowBookingConfirmation(false), 5000);
        return () => clearTimeout(timer);
    }
  }, [showBookingConfirmation]);

  const mapErrorToUserMessage = (error: Error): string => {
    const msg = error.message;
    if (language === 'en') {
        if (msg.includes("API_KEY_MISSING")) return "Configuration Error: API Key missing.";
        if (msg.includes("MIC_PERMISSION_DENIED")) return "Microphone access denied. Please check settings.";
        if (msg.includes("MIC_NOT_FOUND")) return "No microphone detected.";
        if (msg.includes("CONNECTION_ERROR")) return "Network connection interrupted.";
        return "An unexpected error occurred.";
    } else {
        if (msg.includes("API_KEY_MISSING")) return "Error de Configuración: Falta API Key.";
        if (msg.includes("MIC_PERMISSION_DENIED")) return "Acceso al micrófono denegado.";
        if (msg.includes("MIC_NOT_FOUND")) return "Micrófono no encontrado.";
        if (msg.includes("CONNECTION_ERROR")) return "Conexión interrumpida.";
        return "Ocurrió un error inesperado.";
    }
  };

  const handleStartCall = async () => {
    setStatus('connecting');
    setErrorMessage('');

    try {
      const session = await connectLiveSession({
        onOpen: () => {
          setStatus('connected');
