import { ShieldCheck, Activity, Database, Power, Mic2, UploadCloud, Key, Globe, Save, Cpu, HardDrive, FileAudio, BarChart3, RefreshCw, Calendar, Mail } from 'lucide-react';
import { CrmLog, VoiceName, VoiceProvider, UsageStats } from '../types';

interface AdminDashboardProps {
  emergencyMode: boolean;
  setEmergencyMode: (val: boolean) => void;
  voiceName: VoiceName;
  setVoiceName: (voice: VoiceName) => void;
  voiceProvider: VoiceProvider;
  setVoiceProvider: (provider: VoiceProvider) => void;
  deepgramKey: string;
  setDeepgramKey: (key: string) => void;
}

const MOCK_USAGE: UsageStats = {
  tokensUsed: 450230,
  tokensLimit: 1000000,
  minutesUsed: 145,
  minutesLimit: 500,
  costEstimate: 12.45
};

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
    emergencyMode, setEmergencyMode, 
    voiceName, setVoiceName,
    voiceProvider, setVoiceProvider,
    deepgramKey, setDeepgramKey
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'general' | 'voice' | 'training' | 'integrations' | 'usage'>('general');
  const [logs, setLogs] = useState<CrmLog[]>([]);
  const [trainingText, setTrainingText] = useState('');
  const [isTraining, setIsTraining] = useState(false);

  // Integration States
  const [googleClientId, setGoogleClientId] = useState('');
  const [googleClientSecret, setGoogleClientSecret] = useState('');

  const geminiVoices: VoiceName[] = ['Puck', 'Charon', 'Kore', 'Fenrir', 'Zephyr'];
  const deepgramVoices: VoiceName[] = ['asteria-en', 'luna-en', 'orion-en', 'arcas-en'];

  useEffect(() => {
    // Load logs
    try {
      const stored = localStorage.getItem('unitec_crm_logs');
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) setLogs(parsed);
      }
    } catch (e) {
      console.error(e);
    }
  }, []);

  const handleSaveTraining = () => {
    setIsTraining(true);
    // Simulate API call to fine-tune
    setTimeout(() => {
        setIsTraining(false);
        alert("Knowledge Base updated successfully. The AI context has been refreshed.");
    }, 2000);
  };

  const clearLogs = () => {
    if (confirm("Are you sure you want to clear all CRM logs?")) {
        localStorage.removeItem('unitec_crm_logs');
        setLogs([]);
    }
  };

  const renderTabContent = () => {
    switch(activeSubTab) {
        case 'general':
            return (
                <div className="space-y-6">
                    {/* System Status */}
                    <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                        <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-4">System Status</h3>
                        <div className={`p-4 rounded-xl border flex items-center justify-between transition-colors ${
                            emergencyMode ? 'bg-red-50 border-red-200' : 'bg-green-50 border-green-200'
                        }`}>
                            <div className="flex items-center gap-3">
                            <Activity size={24} className={emergencyMode ? "text-red-500 animate-pulse" : "text-green-500"} />
                            <div>
                                <p className={`font-bold text-lg ${emergencyMode ? "text-red-700" : "text-green-700"}`}>
                                    {emergencyMode ? "Emergency Override" : "System Operational"}
                                </p>
                                <p className="text-sm opacity-75">
                                    {emergencyMode ? "Safety Protocols Active - Restricted Responses" : "Normal AI Response Mode - Full Capabilities"}
                                </p>
                            </div>
                            </div>
                            <button 
                            onClick={() => setEmergencyMode(!emergencyMode)}
                            className={`px-4 py-2 rounded-lg font-bold text-sm transition-colors flex items-center gap-2 ${
                                emergencyMode ? 'bg-red-200 text-red-800 hover:bg-red-300' : 'bg-green-200 text-green-800 hover:bg-green-300'
                            }`}
                            >
                            <Power size={16} />
                            {emergencyMode ? "Disable Override" : "Enable Override"}
                            </button>
                        </div>
                    </div>

                    {/* CRM Logs */}
                    <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider">Recent Interactions</h3>
                            <button onClick={clearLogs} className="text-xs text-red-500 hover:text-red-700 font-medium">Clear History</button>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-left">
                                <thead className="text-xs text-gray-500 uppercase bg-gray-50">
                                    <tr>
                                        <th className="px-4 py-3">Time</th>
                                        <th className="px-4 py-3">Customer</th>
                                        <th className="px-4 py-3">Sentiment</th>
                                        <th className="px-4 py-3">Action</th>
                                        <th className="px-4 py-3">Summary</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {logs.length === 0 ? (
                                        <tr><td colSpan={5} className="px-4 py-8 text-center text-gray-400 italic">No logs available</td></tr>
                                    ) : (
                                        logs.slice(0, 5).map(log => (
                                            <tr key={log.id} className="border-b border-gray-100 hover:bg-gray-50">
                                                <td className="px-4 py-3 text-gray-500">{new Date(log.timestamp).toLocaleTimeString()}</td>
                                                <td className="px-4 py-3 font-medium text-gray-800">{log.customerName}</td>
                                                <td className="px-4 py-3">
                                                    <span className={`px-2 py-1 rounded text-xs font-medium ${
                                                        log.sentiment === 'Positive' ? 'bg-green-100 text-green-700' : 
                                                        log.sentiment === 'Negative' ? 'bg-red-100 text-red-700' : 'bg-gray-100 text-gray-600'
                                                    }`}>{log.sentiment}</span>
                                                </td>
                                                <td className="px-4 py-3 text-brand-600">{log.actionTaken}</td>
                                                <td className="px-4 py-3 text-gray-600 max-w-xs truncate">{log.summary}</td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            );
        case 'voice':
            return (
                <div className="space-y-6">
                    {/* Provider Selection */}
                    <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                        <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-4">Voice Engine Configuration</h3>
                        <div className="grid grid-cols-2 gap-4 mb-6">
                             <div 
                                onClick={() => { setVoiceProvider('gemini'); setVoiceName('Kore'); }}
                                className={`cursor-pointer p-4 rounded-xl border-2 transition-all flex items-center gap-4 ${
                                    voiceProvider === 'gemini' ? 'border-brand-500 bg-brand-50' : 'border-gray-200 hover:border-brand-200'
                                }`}
                             >
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${voiceProvider === 'gemini' ? 'bg-brand-500 text-white' : 'bg-gray-200 text-gray-500'}`}>
                                    <Globe size={20} />
                                </div>
                                <div>
                                    <h4 className="font-bold text-gray-800">Gemini Live (Native)</h4>
                                    <p className="text-xs text-gray-500">Low latency, standard voices.</p>
                                </div>
                             </div>

                             <div 
                                onClick={() => { setVoiceProvider('deepgram'); setVoiceName('asteria-en'); }}
                                className={`cursor-pointer p-4 rounded-xl border-2 transition-all flex items-center gap-4 ${
                                    voiceProvider === 'deepgram' ? 'border-purple-500 bg-purple-50' : 'border-gray-200 hover:border-purple-200'
                                }`}
                             >
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${voiceProvider === 'deepgram' ? 'bg-purple-500 text-white' : 'bg-gray-200 text-gray-500'}`}>
                                    <Cpu size={20} />
                                </div>
                                <div>
                                    <h4 className="font-bold text-gray-800">Deepgram Aura</h4>
                                    <p className="text-xs text-gray-500">High fidelity, requires API Key.</p>
                                </div>
                             </div>
                        </div>

                        {voiceProvider === 'deepgram' && (
                            <div className="mb-6">
                                <label className="block text-sm font-medium text-gray-700 mb-1">Deepgram API Key</label>
                                <div className="flex gap-2">
                                    <div className="relative flex-1">
                                        <Key size={16} className="absolute left-3 top-3 text-gray-400" />
                                        <input 
                                            type="password" 
                                            value={deepgramKey}
                                            onChange={(e) => setDeepgramKey(e.target.value)}
                                            className="w-full pl-10 p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 outline-none" 
                                            placeholder="Enter key..."
                                        />
                                    </div>
                                    <button className="bg-purple-600 text-white px-4 py-2 rounded-lg font-medium text-sm">Verify</button>
                                </div>
                            </div>
                        )}

                        <div className="mb-2">
                            <label className="block text-sm font-medium text-gray-700 mb-2">Select Persona</label>
                            <div className="flex flex-wrap gap-2">
                                {(voiceProvider === 'gemini' ? geminiVoices : deepgramVoices).map(v => (
                                    <button
                                        key={v}
                                        onClick={() => setVoiceName(v)}
                                        className={`px-4 py-2 rounded-lg text-sm font-medium border transition-colors ${
                                            voiceName === v 
                                            ? (voiceProvider === 'gemini' ? 'bg-brand-600 text-white border-brand-600' : 'bg-purple-600 text-white border-purple-600')
                                            : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                                        }`}
                                    >
                                        {v.replace('-en', '')}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Voice Cloning Lab (Enterprise Feature) */}
                    <div className="bg-white p-6 rounded-xl border border-dashed border-gray-300 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 bg-accent-500 text-white text-xs font-bold px-3 py-1 rounded-bl-xl shadow-sm z-10">
                            ENTERPRISE ADD-ON
                        </div>

                        <div className="flex items-start gap-4">
                            <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center shrink-0">
                                <Mic2 size={24} />
                            </div>
                            <div className="flex-1">
                                <h3 className="text-lg font-bold text-gray-800">Custom Voice Cloning Lab</h3>
                                <p className="text-sm text-gray-500 mb-4">
                                    Upload a high-quality audio sample (min 30s) to train a custom neural voice model for your brand.
                                </p>

                                <div className="border-2 border-dashed border-indigo-100 rounded-xl p-8 text-center hover:bg-indigo-50/50 transition-colors cursor-pointer">
                                    <UploadCloud size={48} className="text-indigo-300 mx-auto mb-3" />
                                    <p className="text-sm font-medium text-indigo-900">Drag and drop audio file here</p>
                                    <p className="text-xs text-indigo-400">.WAV or .MP3 (Max 10MB)</p>
                                    <button className="mt-4 bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-indigo-700">
                                        Select File
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Call Recordings Library */}
                     <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                        <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-4">Call Recording Library</h3>
                        <div className="space-y-2">
                            {[1, 2, 3].map(i => (
                                <div key={i} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-100">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 bg-white rounded flex items-center justify-center text-gray-400 border border-gray-200">
                                            <FileAudio size={16} />
                                        </div>
                                        <div>
                                            <p className="text-sm font-medium text-gray-700">Call_Recording_{100 + i}.wav</p>
                                            <p className="text-xs text-gray-400">Oct {10 + i}, 2024 • 2:1{i} PM</p>
                                        </div>
                                    </div>
                                    <button className="text-xs text-brand-600 hover:underline font-medium">Download</button>
                                </div>
                            ))}
                        </div>
                     </div>
                </div>
            );
        case 'training':
            return (
                <div className="space-y-6">
                    <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm h-full flex flex-col">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                                    <Database size={20} className="text-brand-500"/> 
                                    Knowledge Base & Training
                                </h3>
                                <p className="text-sm text-gray-500">Update the context data provided to the AI model. Changes apply to the next session.</p>
                            </div>
                            <button 
                                onClick={handleSaveTraining}
                                disabled={isTraining}
                                className="bg-brand-600 text-white px-4 py-2 rounded-lg font-medium flex items-center gap-2 hover:bg-brand-700 disabled:opacity-50"
                            >
                                {isTraining ? <RefreshCw className="animate-spin" size={16}/> : <Save size={16}/>}
                                {isTraining ? 'Training...' : 'Save & Retrain'}
                            </button>
                        </div>

                        <div className="flex-1">
                            <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">System Instructions Override</label>
                            <textarea
                                className="w-full h-96 p-4 border border-gray-300 rounded-xl focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none font-mono text-sm leading-relaxed text-slate-700 bg-slate-50"
                                placeholder="// Enter specific business rules, product updates, or behavioral guidelines here...
Example:
- Promote the new 'Eco-Friendly' line of WPC panels.
- Do not offer discounts greater than 15% without manager approval."
                                value={trainingText}
                                onChange={(e) => setTrainingText(e.target.value)}
                            ></textarea>
                        </div>
                        <div className="mt-4 p-4 bg-blue-50 text-blue-800 rounded-lg text-sm flex items-start gap-3">
                            <HardDrive size={18} className="shrink-0 mt-0.5" />
                            <p>Data entered here is appended to the base prompt. For large-scale document ingestion (PDFs, CSVs), please contact enterprise support for vector database integration.</p>
                        </div>
                    </div>
                </div>
            );
        case 'usage':
            return (
                <div className="space-y-6">
                     <div className="grid grid-cols-3 gap-6">
                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                            <p className="text-xs text-gray-500 uppercase font-bold tracking-wider mb-1">Current Cost</p>
                            <h3 className="text-3xl font-extrabold text-slate-800">${MOCK_USAGE.costEstimate.toFixed(2)}</h3>
                            <p className="text-xs text-green-600 mt-2 flex items-center gap-1">
                                <Activity size={12}/> +$2.10 this week
                            </p>
                        </div>
                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                            <p className="text-xs text-gray-500 uppercase font-bold tracking-wider mb-1">Calls Processed</p>
                            <h3 className="text-3xl font-extrabold text-slate-800">42</h3>
                            <p className="text-xs text-gray-400 mt-2">Last 30 days</p>
                        </div>
                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                            <p className="text-xs text-gray-500 uppercase font-bold tracking-wider mb-1">Avg Latency</p>
                            <h3 className="text-3xl font-extrabold text-slate-800">320ms</h3>
                            <p className="text-xs text-green-600 mt-2">Optimal range</p>
                        </div>
                     </div>

                     <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                        <h3 className="text-lg font-bold text-gray-800 mb-6 flex items-center gap-2">
                            <BarChart3 size={20} className="text-brand-500" /> Usage Limits
                        </h3>

                        <div className="space-y-6">
                            <div>
                                <div className="flex justify-between text-sm mb-2">
                                    <span className="font-medium text-gray-700">Token Usage (Input/Output)</span>
                                    <span className="text-gray-500">{MOCK_USAGE.tokensUsed.toLocaleString()} / {MOCK_USAGE.tokensLimit.toLocaleString()}</span>
                                </div>
                                <div className="w-full bg-gray-100 rounded-full h-3 overflow-hidden">
                                    <div className="bg-brand-500 h-full rounded-full" style={{ width: `${(MOCK_USAGE.tokensUsed / MOCK_USAGE.tokensLimit) * 100}%` }}></div>
                                </div>
                            </div>

                            <div>
                                <div className="flex justify-between text-sm mb-2">
                                    <span className="font-medium text-gray-700">Audio Synthesis (Minutes)</span>
                                    <span className="text-gray-500">{MOCK_USAGE.minutesUsed} / {MOCK_USAGE.minutesLimit} mins</span>
                                </div>
                                <div className="w-full bg-gray-100 rounded-full h-3 overflow-hidden">
                                    <div className="bg-purple-500 h-full rounded-full" style={{ width: `${(MOCK_USAGE.minutesUsed / MOCK_USAGE.minutesLimit) * 100}%` }}></div>
                                </div>
                            </div>
                        </div>
                     </div>
                </div>
            );
        case 'integrations':
            return (
                <div className="space-y-6">
                     <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                        <h3 className="text-lg font-bold text-gray-800 mb-1">Google Workspace Integration</h3>
                        <p className="text-sm text-gray-500 mb-6">Connect Calendar and Gmail to enable scheduling automation.</p>

                        <div className="space-y-4 max-w-lg">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Google Client ID</label>
                                <input 
                                    type="text" 
                                    value={googleClientId}
                                    onChange={(e) => setGoogleClientId(e.target.value)}
                                    className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand-500 outline-none text-sm font-mono"
                                    placeholder="000000000-xxxxxxxx.apps.googleusercontent.com"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Google Client Secret</label>
                                <input 
                                    type="password" 
                                    value={googleClientSecret}
                                    onChange={(e) => setGoogleClientSecret(e.target.value)}
                                    className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-brand-500 outline-none text-sm font-mono"
                                    placeholder="GOCSPX-xxxxxxxxxxxx"
                                />
                            </div>

                            <div className="pt-4 flex items-center gap-4">
                                <button className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg font-medium hover:bg-gray-50 flex items-center gap-2">
                                    <Calendar size={16} /> Test Calendar
                                </button>
                                <button className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg font-medium hover:bg-gray-50 flex items-center gap-2">
                                    <Mail size={16} /> Test Email
                                </button>
                                <button className="ml-auto bg-brand-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-brand-700">
                                    Connect Account
                                </button>
                            </div>
                        </div>
                     </div>
                </div>
            );
        default: return null;
