const ESCALA_API_BASE = "https://api.escala.com/v1";

export const getEscalaConfig = (): EscalaConfig => {
  const stored = localStorage.getItem('unitec_escala_config');
  if (stored) return JSON.parse(stored);
  return { apiKey: '', accountId: '', isActive: false };
};

export const saveEscalaConfig = (config: EscalaConfig) => {
  localStorage.setItem('unitec_escala_config', JSON.stringify(config));
};

export const syncLeadToEscala = async (data: {
  name: string;
  email?: string;
  phone?: string;
  message: string;
  tags: string[];
  customFields?: Record<string, string>;
}) => {
  const config = getEscalaConfig();
  if (!config.isActive || !config.apiKey) {
    console.warn("Escala Integration not active. Skipping sync.");
    return { success: false, reason: 'inactive' };
  }

  try {
    // Escala Lead Capture Endpoint
    // Note: We use the generic lead creation pattern as per Escala's integration docs
    const response = await fetch(`${ESCALA_API_BASE}/contacts`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${config.apiKey}`,
        'Content-Type': 'application/json',
        'X-Account-Id': config.accountId
      },
      body: JSON.stringify({
        first_name: data.name,
        email: data.email || `visitor_${Date.now()}@unitec-ai.com`,
        phone: data.phone || '',
        description: data.message,
        tags: data.tags,
        custom_fields: {
          ...data.customFields,
          source: 'AI_FRONT_DESK'
        }
      })
    });

    if (!response.ok) {
      const err = await response.text();
      throw new Error(`Escala API Error: ${err}`);
    }

    return { success: true };
  } catch (error) {
    console.error("Failed to sync with Escala:", error);
    return { success: false, reason: 'error', error };
  }
};

export const testEscalaConnection = async (config: EscalaConfig) => {
  try {
    const response = await fetch(`${ESCALA_API_BASE}/account/me`, {
      headers: {
        'Authorization': `Bearer ${config.apiKey}`,
        'X-Account-Id': config.accountId
      }
    });
    return response.ok;
  } catch (e) {
    return false;
  }
};

