import React, { useState, useEffect } from 'react';
import { ShieldCheck, Activity, Database, Power, Mic2, UploadCloud, Key, Globe, Save, Cpu, HardDrive, FileAudio, BarChart3, RefreshCw, Calendar, Mail, Link, Check, Loader2, Volume2, Settings, Download, Play, Music } from 'lucide-react';
import { CrmLog, VoiceName, VoiceProvider, UsageStats, EscalaConfig, CallRecording } from '../types';
import { playGeminiTTS } from '../services/geminiService';
import { playDeepgramTTS } from '../services/deepgramService';
import { getEscalaConfig, saveEscalaConfig, testEscalaConnection } from '../services/escalaService';

interface AdminDashboardProps {
  emergencyMode: boolean;
  setEmergencyMode: (val: boolean) => void;
  voiceName: VoiceName;
  setVoiceName: (voice: VoiceName) => void;
  voiceProvider: VoiceProvider;
  setVoiceProvider: (provider: VoiceProvider) => void;
  deepgramKey: string;
  setDeepgramKey: (key: string) => void;
}

const MOCK_USAGE: UsageStats = {
  tokensUsed: 450230,
  tokensLimit: 1000000,
  minutesUsed: 145,
  minutesLimit: 500,
  costEstimate: 12.45
};

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
    emergencyMode, setEmergencyMode, 
    voiceName, setVoiceName,
    voiceProvider, setVoiceProvider,
    deepgramKey, setDeepgramKey
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'general' | 'voice' | 'training' | 'integrations' | 'usage'>('voice');
  const [logs, setLogs] = useState<CrmLog[]>([]);
  const [recordings, setRecordings] = useState<CallRecording[]>([]);

  // Escala CRM States
  const [escalaConfig, setEscalaConfig] = useState<EscalaConfig>({ apiKey: '', accountId: '', isActive: false });
  const [isEscalaConnecting, setIsEscalaConnecting] = useState(false);

  // Voice Lab States
  const [voiceUploadStatus, setVoiceUploadStatus] = useState<'idle' | 'uploading' | 'success'>('idle');
  const [uploadedFileName, setUploadedFileName] = useState('');
  const [isTestingVoice, setIsTestingVoice] = useState<string | null>(null);

  const geminiVoices: VoiceName[] = ['Puck', 'Charon', 'Kore', 'Fenrir', 'Zephyr'];
  if (voiceUploadStatus === 'success') {
      geminiVoices.push('Clone-1');
  }
  const deepgramVoices: VoiceName[] = ['asteria-en', 'luna-en', 'orion-en', 'arcas-en'];

  useEffect(() => {
    // Load logs
    const storedLogs = localStorage.getItem('unitec_crm_logs');
    if (storedLogs) setLogs(JSON.parse(storedLogs));

    // Load library
    const storedLib = localStorage.getItem('unitec_call_library');
    if (storedLib) setRecordings(JSON.parse(storedLib));

    // Load Escala
    setEscalaConfig(getEscalaConfig());
  }, []);

  const handleVoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
        const file = e.target.files[0];
        setUploadedFileName(file.name);
        setVoiceUploadStatus('uploading');
        setTimeout(() => {
            setVoiceUploadStatus('success');
        }, 3000);
    }
  };

  const handleTestVoice = async (v: VoiceName) => {
    if (isTestingVoice) return;
    setIsTestingVoice(v);
    const sampleText = "Welcome to UNITEC USA DESIGN. This is a sample of our custom cloned voice model.";
    try {
        if (voiceProvider === 'gemini') {
            await playGeminiTTS(sampleText, v === 'Clone-1' ? 'Zephyr' : v); // Simulating clone by using Zephyr for the test
        } else {
            if (!deepgramKey) return;
            await playDeepgramTTS(sampleText, deepgramKey, v, () => {}, () => setIsTestingVoice(null));
        }
        setTimeout(() => setIsTestingVoice(null), 3000);
    } catch (e) {
        setIsTestingVoice(null);
    }
  };

  const renderTabContent = () => {
    switch(activeSubTab) {
        case 'voice':
            return (
                <div className="space-y-8 animate-in fade-in duration-500">
                    {/* Voice Selection */}
                    <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-6">Select & Test Persona</h3>
                        <div className="flex flex-wrap gap-4">
                            {(voiceProvider === 'gemini' ? geminiVoices : deepgramVoices).map(v => (
                                <div key={v} className="flex items-center">
                                    <button
                                        onClick={() => setVoiceName(v)}
