                    <div className="bg-white p-8 rounded-2xl border border-gray-100 shadow-sm relative overflow-hidden">
                        <div className="absolute top-4 right-4 bg-orange-500 text-white text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-widest">Enterprise Add-on</div>

                        <div className="flex items-start gap-5 mb-8">
                            <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center shrink-0 shadow-inner">
                                <Mic2 size={24} />
                            </div>
                            <div>
                                <h3 className="text-lg font-bold text-slate-800">Custom Voice Cloning Lab</h3>
                                <p className="text-sm text-slate-500">Upload a high-quality audio sample (min 30s) to train a custom neural voice model for your brand.</p>
                            </div>
                        </div>

                        <div className={`rounded-2xl border-2 border-dashed transition-all duration-500 ${
                            voiceUploadStatus === 'idle' ? 'border-slate-200 bg-slate-50 p-12 text-center' : 
                            voiceUploadStatus === 'uploading' ? 'border-brand-300 bg-brand-50 p-12 text-center shadow-lg shadow-brand-500/5' :
                            'border-emerald-200 bg-emerald-50 p-12 text-center'
                        }`}>
                            {voiceUploadStatus === 'idle' ? (
                                <label className="cursor-pointer flex flex-col items-center group">
                                    <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center shadow-sm mb-4 group-hover:scale-110 transition-transform">
                                        <UploadCloud size={32} className="text-brand-500" />
                                    </div>
                                    <span className="text-sm font-bold text-slate-600 mb-1">Click to upload voice sample</span>
                                    <span className="text-xs text-slate-400 font-medium">MP3, WAV, or OGG (Recommended: 1 min speech)</span>
                                    <input type="file" className="hidden" onChange={handleVoiceUpload} accept="audio/*" />
                                </label>
                            ) : voiceUploadStatus === 'uploading' ? (
                                <div className="flex flex-col items-center">
                                    <div className="relative mb-6">
                                        <Loader2 size={64} className="text-brand-500 animate-spin" />
                                        <div className="absolute inset-0 flex items-center justify-center text-[10px] font-bold text-brand-600">AI</div>
                                    </div>
                                    <span className="text-sm font-bold text-brand-700">Neural Training in Progress...</span>
                                    <span className="text-xs text-brand-400 mt-1">Analyzing frequencies in {uploadedFileName}</span>
                                    <div className="w-48 bg-brand-100 h-1 rounded-full mt-4 overflow-hidden">
                                        <div className="bg-brand-500 h-full animate-[progress_4s_ease-in-out]"></div>
                                    </div>
                                </div>
                            ) : (
                                <div className="flex flex-col items-center animate-in zoom-in-95 duration-500">
                                    <div className="w-16 h-16 bg-emerald-500 text-white rounded-full flex items-center justify-center mb-4 shadow-lg shadow-emerald-500/20">
                                        <Check size={32} />
                                    </div>
                                    <span className="text-sm font-bold text-emerald-700">Custom Voice Trained!</span>
                                    <span className="text-xs text-emerald-600 mt-1">Model 'Clone-1' generated successfully.</span>
                                    <p className="text-xs text-emerald-500 mt-4 max-w-sm leading-relaxed">The cloned voice is now available in your "Voice Selection" list above. It will be used for all future AI interactions.</p>
                                    <button 
                                        onClick={() => {
                                            setVoiceUploadStatus('idle');
                                            localStorage.removeItem('unitec_voice_clone_ready');
                                            setIsCloneUnlocked(false);
                                        }}
                                        className="mt-6 text-xs font-bold text-slate-400 uppercase tracking-widest hover:text-red-500 transition-colors"
                                    >
                                        Reset Model
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Call Recording Library */}
                    <div className="bg-white p-8 rounded-2xl border border-gray-100 shadow-sm">
                        <div className="flex items-center justify-between mb-6">
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Call Recording Library</h3>
                            <span className="text-[10px] text-slate-400 font-bold uppercase">{recordings.length} Recorded Sessions</span>
                        </div>
                        <div className="space-y-3">
                            {recordings.length === 0 ? (
                                <div className="p-12 text-center border rounded-xl bg-slate-50 text-slate-400 italic text-sm">No recordings yet. Interaction recordings appear here automatically.</div>
                            ) : (
                                recordings.map((rec) => (
                                    <div key={rec.id} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 rounded-xl hover:bg-white hover:shadow-lg transition-all group border-l-4 border-l-brand-200">
                                        <div className="flex items-center gap-4">
                                            <div className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${
                                                playingId === rec.id ? 'bg-brand-500 text-white animate-pulse' : 'bg-white border border-slate-200 text-slate-400'
                                            }`}>
                                                {playingId === rec.id ? <Pause size={20} /> : <Music size={20} />}
                                            </div>
                                            <div>
                                                <p className="text-sm font-bold text-slate-800">{rec.name}</p>
                                                <div className="flex items-center gap-2 mt-0.5">
                                                    <p className="text-[10px] text-slate-400 font-bold uppercase">
                                                        {new Date(rec.timestamp).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} • {new Date(rec.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                    </p>
                                                    <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
                                                    <p className="text-[10px] text-slate-500 font-bold">{rec.duration}</p>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={() => togglePlayback(rec)}
                                                className={`p-2.5 rounded-full transition-all ${
                                                    playingId === rec.id ? 'bg-red-50 text-red-500' : 'bg-white text-brand-600 border border-brand-100 hover:bg-brand-50'
                                                }`}
                                            >
                                                {playingId === rec.id ? <Pause size={18} /> : <Play size={18} />}
                                            </button>
                                            <button 
                                                onClick={() => handleDownload(rec)}
                                                className="px-5 py-2 text-[10px] font-bold text-slate-600 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-all uppercase tracking-widest shadow-sm"
                                            >
                                                Download
                                            </button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            );
        // ... rest of cases (general, integrations, etc)
        default: return <div className="p-12 text-center text-gray-400">Section loaded</div>;
    }
  };

  return (
    <div className="h-full flex flex-col bg-slate-50">
        <div className="border-b border-gray-200 bg-white px-6 py-2 flex gap-6 shrink-0 overflow-x-auto no-scrollbar">
             <button onClick={() => setActiveSubTab('general')} className={`py-3 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeSubTab === 'general' ? 'border-brand-600 text-brand-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>General</button>
             <button onClick={() => setActiveSubTab('voice')} className={`py-3 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeSubTab === 'voice' ? 'border-brand-600 text-brand-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Voice Lab</button>
             <button onClick={() => setActiveSubTab('integrations')} className={`py-3 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeSubTab === 'integrations' ? 'border-brand-600 text-brand-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Integrations</button>
             <button onClick={() => setActiveSubTab('usage')} className={`py-3 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeSubTab === 'usage' ? 'border-brand-600 text-brand-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Usage</button>
        </div>

        <div className="flex-1 overflow-y-auto p-8">
            <div className="max-w-4xl mx-auto">
                {renderTabContent()}
            </div>
        </div>
    </div>
  );
};

