import React, { useState, useRef, useEffect } from 'react';
import { Message, QuickAction, Language } from '../types';
import { sendMessageToGemini } from '../services/geminiService';
import { Send, Bot, User, Loader2, Box, DollarSign, Hammer, BookOpen, AlertTriangle, CheckCircle2 } from 'lucide-react';
import { GenerateContentResponse } from '@google/genai';
import { UI_TRANSLATIONS } from '../constants';

interface ChatTabProps {
  quickActions: QuickAction[];
  initialMessage?: string;
  emergencyMode?: boolean;
  language: Language;
}

const ChatTab: React.FC<ChatTabProps> = ({ quickActions, initialMessage, emergencyMode, language }) => {
  const t = UI_TRANSLATIONS[language];

  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      text: t.chatWelcome,
      timestamp: new Date()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [showBookingConfirmation, setShowBookingConfirmation] = useState(false);
  const [confirmedDate, setConfirmedDate] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const hasProcessedInitial = useRef(false);

  // Update welcome message when language changes, but only if it's the only message
  useEffect(() => {
    if (messages.length === 1 && messages[0].id === 'welcome') {
        setMessages([{
            id: 'welcome',
            role: 'model',
            text: t.chatWelcome,
            timestamp: new Date()
        }]);
    }
  }, [language, t.chatWelcome]);

  // Check for API Key on mount
  useEffect(() => {
    if (!process.env.API_KEY) {
      setError("System Error: API Key is missing. Please contact support.");
    }
  }, []);

  useEffect(() => {
    if (initialMessage && !hasProcessedInitial.current && !isLoading && !error) {
      hasProcessedInitial.current = true;
      handleSendMessage(initialMessage);
    }
  }, [initialMessage]);

  useEffect(() => {
    if (showBookingConfirmation) {
        const timer = setTimeout(() => setShowBookingConfirmation(false), 8000);
        return () => clearTimeout(timer);
    }
  }, [showBookingConfirmation]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const handleSendMessage = async (text: string) => {
    if (!text.trim() || isLoading) return;

    // Clear previous errors
    setError(null);

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      const responseGenerator = sendMessageToGemini(
          text, 
          emergencyMode, 
          language,
          (toolName, result) => {
              if (toolName === 'book_appointment') {
                  setConfirmedDate(result.date || null);
                  setShowBookingConfirmation(true);
              }
          }
      );

      const botMsgId = (Date.now() + 1).toString();
      setMessages(prev => [...prev, {
        id: botMsgId,
        role: 'model',
        text: '', // Start empty
        timestamp: new Date()
      }]);

      let fullText = '';

      for await (const chunk of responseGenerator) {
        const c = chunk as GenerateContentResponse;
        const chunkText = c.text || '';
        fullText += chunkText;

        setMessages(prev => prev.map(msg => 
          msg.id === botMsgId ? { ...msg, text: fullText } : msg
        ));
      }
    } catch (error: any) {
      console.error("Chat error:", error);
      let errorMsg = language === 'en' ? "I'm having trouble connecting. Please try again." : "Tengo problemas de conexión. Inténtalo de nuevo.";

      if (error.message?.includes("API_KEY_MISSING")) {
        errorMsg = language === 'en' ? "Configuration Error: API Key is missing." : "Error de Configuración: Falta la API Key.";
      }

      setError(errorMsg);

      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: language === 'en' ? "⚠️ Connection interrupted. Please check your internet." : "⚠️ Conexión interrumpida. Revisa tu internet.",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const getIcon = (name: string) => {
    switch(name) {
      case 'Box': return <Box size={16} />;
      case 'DollarSign': return <DollarSign size={16} />;
      case 'Hammer': return <Hammer size={16} />;
      case 'BookOpen': return <BookOpen size={16} />;
      default: return <Box size={16} />;
    }
  };

  return (
    <div className="flex flex-col h-full relative">

      {/* Success Banner Overlay */}
      <div className={`absolute top-4 left-4 right-4 z-50 transition-all duration-500 transform ${showBookingConfirmation ? 'translate-y-0 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'}`}>
        <div className="bg-emerald-50 border-2 border-emerald-200 text-emerald-800 p-5 rounded-2xl shadow-2xl flex items-center gap-4">
            <div className="bg-emerald-100 p-2 rounded-full text-emerald-600 ring-4 ring-emerald-50">
                <CheckCircle2 size={28} />
            </div>
            <div>
                <p className="font-bold text-sm uppercase tracking-wider text-emerald-600">Action Confirmed</p>
                <p className="text-sm font-medium">{t.bookingConfirmed}</p>
                {confirmedDate && (
                  <p className="text-xs font-bold mt-1 text-emerald-700 bg-emerald-100/50 px-2 py-0.5 rounded-md inline-block">{confirmedDate}</p>
                )}
            </div>
        </div>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6 no-scrollbar relative">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`flex max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-end gap-2`}>
              <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${
                msg.role === 'user' ? 'bg-brand-500 text-white' : 'bg-brand-900 text-accent-500'
              }`}>
                {msg.role === 'user' ? <User size={16} /> : <Bot size={16} />}
              </div>
              <div 
                className={`p-3.5 rounded-2xl text-sm leading-relaxed shadow-sm ${
                  msg.role === 'user' 
                    ? 'bg-brand-500 text-white rounded-br-none' 
                    : 'bg-white text-gray-800 rounded-bl-none border border-gray-100'
                }`}
              >
                 {msg.text.split('\n').map((line, i) => (
                    <p key={i} className={i > 0 ? 'mt-2' : ''}>{line}</p>
                 ))}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
             <div className="flex max-w-[85%] items-end gap-2">
                <div className="w-8 h-8 rounded-full bg-brand-900 text-accent-500 flex items-center justify-center shrink-0">
                  <Bot size={16} />
                </div>
                <div className="bg-white p-3 rounded-2xl rounded-bl-none border border-gray-100 shadow-sm flex items-center gap-3">
                  <div className="flex gap-1">
                    <div className="w-1.5 h-1.5 bg-brand-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                    <div className="w-1.5 h-1.5 bg-brand-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                    <div className="w-1.5 h-1.5 bg-brand-400 rounded-full animate-bounce"></div>
                  </div>
                  <span className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">
                    {language === 'en' ? 'typing...' : 'escribiendo...'}
                  </span>
                </div>
             </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Error Banner */}
      {error && (
        <div className="px-4 pb-2">
          <div className="bg-red-50 border border-red-100 text-red-700 px-3 py-2 rounded-lg text-xs flex items-center gap-2">
            <AlertTriangle size={14} />
            <span>{error}</span>
          </div>
        </div>
      )}

      {/* Quick Actions */}
      <div className="px-4 py-2">
         <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
            {quickActions.map(action => (
              <button
                key={action.id}
                onClick={() => handleSendMessage(action.message)}
                disabled={isLoading || !!error}
                className="flex items-center gap-2 whitespace-nowrap bg-white border border-brand-100 px-3 py-2 rounded-full text-xs font-medium text-brand-700 hover:bg-brand-50 hover:border-brand-300 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {getIcon(action.iconName)}
                {action.title}
              </button>
            ))}
         </div>
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t border-gray-100">
        <div className={`flex items-center gap-2 bg-gray-50 p-2 rounded-xl border transition-all ${
          error ? 'border-red-200' : 'border-gray-200 focus-within:border-brand-500 focus-within:ring-1 focus-within:ring-brand-500'
        }`}>
          <input
            type="text"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage(inputText)}
            placeholder={error ? (language === 'en' ? "Chat disabled" : "Chat deshabilitado") : t.chatPlaceholder}
            className="flex-1 bg-transparent border-none outline-none text-sm px-2 text-gray-800 placeholder-gray-400 disabled:text-gray-400"
            disabled={isLoading || !!error}
          />
          <button 
            onClick={() => handleSendMessage(inputText)}
            disabled={!inputText.trim() || isLoading || !!error}
            className={`p-2 rounded-lg transition-colors ${
              inputText.trim() && !isLoading && !error
                ? 'bg-brand-600 text-white hover:bg-brand-700 shadow-md' 
                : 'bg-gray-200 text-gray-400 cursor-not-allowed'
            }`}
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatTab;

import React, { useState, useEffect, useRef } from 'react';
import { ShieldCheck, Activity, Database, Power, Mic2, UploadCloud, Key, Globe, Save, Cpu, HardDrive, FileAudio, BarChart3, RefreshCw, Calendar, Mail, Link, Check, Loader2, Volume2, Settings, Download, Play, Music, Pause, CheckCircle2, Server, Terminal, ExternalLink, Headphones } from 'lucide-react';
import { CrmLog, VoiceName, VoiceProvider, UsageStats, EscalaConfig, CallRecording } from '../types';
import { playGeminiTTS } from '../services/geminiService';
import { playDeepgramTTS } from '../services/deepgramService';
import { getEscalaConfig, saveEscalaConfig, testEscalaConnection } from '../services/escalaService';

interface AdminDashboardProps {
  emergencyMode: boolean;
  setEmergencyMode: (val: boolean) => void;
  voiceName: VoiceName;
  setVoiceName: (voice: VoiceName) => void;
  voiceProvider: VoiceProvider;
  setVoiceProvider: (provider: VoiceProvider) => void;
  deepgramKey: string;
  setDeepgramKey: (key: string) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
    emergencyMode, setEmergencyMode, 
    voiceName, setVoiceName,
    voiceProvider, setVoiceProvider,
    deepgramKey, setDeepgramKey
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'general' | 'voice' | 'integrations' | 'usage'>('voice');
  const [logs, setLogs] = useState<CrmLog[]>([]);
  const [recordings, setRecordings] = useState<CallRecording[]>([]);
  const [isSavingKey, setIsSavingKey] = useState(false);

  // Voice Lab States
  const [voiceUploadStatus, setVoiceUploadStatus] = useState<'idle' | 'uploading' | 'success'>('idle');
  const [uploadedFileName, setUploadedFileName] = useState('');
  const [isTestingVoice, setIsTestingVoice] = useState<string | null>(null);
  const [testFeedback, setTestFeedback] = useState<string | null>(null);

  // Playback state
  const [playingId, setPlayingId] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const geminiVoices: VoiceName[] = ['Puck', 'Charon', 'Kore', 'Fenrir', 'Zephyr'];
  const deepgramVoices: VoiceName[] = ['asteria-en', 'luna-en', 'orion-en', 'arcas-en'];

  // Persistent voice clone status check
  const [customClones, setCustomClones] = useState<string[]>([]);

  useEffect(() => {
    const savedClones = localStorage.getItem('unitec_voice_clones');
    if (savedClones) {
        setCustomClones(JSON.parse(savedClones));
    }

    const storedLogs = localStorage.getItem('unitec_crm_logs');
    if (storedLogs) setLogs(JSON.parse(storedLogs));

    const storedLib = localStorage.getItem('unitec_call_library');
    if (storedLib) setRecordings(JSON.parse(storedLib));
  }, []);

  const handleVoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
        const file = e.target.files[0];
        const cleanName = file.name.split('.')[0].replace(/[^a-zA-Z0-9]/g, '_');
        setUploadedFileName(file.name);
        setVoiceUploadStatus('uploading');

        setTimeout(() => {
            setVoiceUploadStatus('success');
            const updatedClones = [...new Set([...customClones, cleanName])];
            setCustomClones(updatedClones);
            localStorage.setItem('unitec_voice_clones', JSON.stringify(updatedClones));

            setVoiceName(cleanName);
            setVoiceProvider('gemini');
        }, 4000);
    }
  };

  const handleTestVoice = async (v: VoiceName) => {
    if (isTestingVoice) return;
    setIsTestingVoice(v);
    setTestFeedback(null);
    const sampleText = "Welcome to UNITEC USA DESIGN. This is a preview of the selected voice profile.";
    try {
        if (voiceProvider === 'gemini') {
            const isClone = customClones.includes(v as string);
            await playGeminiTTS(sampleText, isClone ? 'Zephyr' : v);
            setTestFeedback(`${v} connected successfully.`);
        } else {
            if (!deepgramKey) {
                alert("Please configure Deepgram API Key in Integrations first.");
                setIsTestingVoice(null);
                return;
            }
            await playDeepgramTTS(sampleText, deepgramKey, v, () => {}, () => {
              setIsTestingVoice(null);
              setTestFeedback(`${v.replace('-en', '')} (Deepgram) ready.`);
            });
        }
        if (voiceProvider === 'gemini') {
          setTimeout(() => {
            setIsTestingVoice(null);
          }, 3000);
        }
    } catch (e) {
        setIsTestingVoice(null);
        setTestFeedback("Voice test failed. Please check configuration.");
    }
  };

  const togglePlayback = (recording: CallRecording) => {
    if (playingId === recording.id) {
        audioRef.current?.pause();
        setPlayingId(null);
    } else {
        if (audioRef.current) {
            audioRef.current.pause();
        }
        const url = recording.blobUrl || "https://www.soundjay.com/buttons/beep-01a.mp3";
        const audio = new Audio(url);
        audio.onended = () => setPlayingId(null);
        audio.play();
        audioRef.current = audio;
        setPlayingId(recording.id);
    }
  };

  const handleDownload = (rec: CallRecording) => {
    if (rec.blobUrl) {
        const link = document.createElement('a');
        link.href = rec.blobUrl;
        link.download = rec.name;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } else {
        alert("Audio file link not available in this demo mode.");
    }
  };

  const currentVoiceList = [...geminiVoices, ...customClones];

  const renderTabContent = () => {
    switch(activeSubTab) {
        case 'voice':
            return (
                <div className="space-y-8 animate-in slide-in-from-bottom-2 duration-500">
                    {/* Provider Toggle */}
                    <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Voice Engine Provider</h3>
                        <div className="flex gap-4 p-1 bg-slate-100 rounded-xl w-fit">
                            <button 
                                onClick={() => setVoiceProvider('gemini')}
                                className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${voiceProvider === 'gemini' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Gemini Live
                            </button>
                            <button 
                                onClick={() => setVoiceProvider('deepgram')}
                                className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${voiceProvider === 'deepgram' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Deepgram Aura
                            </button>
                        </div>
                    </div>

                    {/* Voice Selection */}
                    <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                        <div className="flex justify-between items-center mb-6">
                            <div className="flex flex-col gap-1">
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Select & Test Persona</h3>
                                {testFeedback && (
                                  <div className="flex items-center gap-1.5 text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-full border border-emerald-100 animate-in fade-in slide-in-from-left-2">
                                    <Check size={10} />
                                    {testFeedback}
                                  </div>
                                )}
                            </div>
                            {customClones.length > 0 && voiceProvider === 'gemini' && (
                                <span className="bg-emerald-100 text-emerald-700 text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-tight">
                                    {customClones.length} Clones Available
                                </span>
                            )}
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            {(voiceProvider === 'gemini' ? currentVoiceList : deepgramVoices).map(v => (
                                <div key={v} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${
                                    voiceName === v 
                                    ? 'bg-brand-50 border-brand-200 ring-2 ring-brand-500/20' 
                                    : 'bg-white border-gray-200 hover:border-brand-200'
                                }`}>
                                    <div className="flex items-center gap-3">
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center ${voiceName === v ? 'bg-brand-500 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>
                                            <Headphones size={16} />
                                        </div>
                                        <button
                                            onClick={() => setVoiceName(v)}
                                            className="text-left"
                                        >
                                            <p className={`text-sm font-bold ${voiceName === v ? 'text-brand-700' : 'text-slate-700'}`}>
                                                {customClones.includes(v as string) ? `${v}` : v.replace('-en', '')}
                                            </p>
                                            <p className="text-[10px] text-slate-400 font-medium">
                                                {voiceName === v ? 'Active Channel' : 'Select Voice'}
                                            </p>
