import { UsageStats, BillingInvoice } from "../types";

/**
 * AI Power Usage Service (SaaS Tier)
 * Tracks token consumption and session durations to calculate client billing.
 */

const STORAGE_KEY = 'unitec_usage_metrics';

// Rates configured for Enterprise Billing
const RATE_PER_1M_TOKENS = 0.25; // Mark-up rate for client billing
const RATE_PER_VOICE_MINUTE = 0.05; // Mark-up rate for voice time

const INITIAL_STATS: UsageStats = {
  totalTokens: 0,
  chatTokens: 0,
  voiceTokens: 0,
  imageTokens: 0,
  minutesUsed: 0,
  apiCalls: 0,
  limitTokens: 10000000,
  limitMinutes: 5000,
  costEstimate: 0,
  billingHistory: [],
  dailyHistory: []
};

export const getUsageStats = (): UsageStats => {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (!stored) return { ...INITIAL_STATS };

  const stats = JSON.parse(stored) as UsageStats;
  // Recalculate cost estimate on retrieval based on current mark-up rates
  stats.costEstimate = (stats.totalTokens / 1000000) * RATE_PER_1M_TOKENS + (stats.minutesUsed * RATE_PER_VOICE_MINUTE);
  return stats;
};

export const trackUsage = (update: Partial<Omit<UsageStats, 'costEstimate' | 'dailyHistory' | 'billingHistory'>>) => {
  const current = getUsageStats();
  const dateStr = new Date().toISOString().split('T')[0];

  const updated: UsageStats = {
    ...current,
    totalTokens: current.totalTokens + (update.totalTokens || 0),
    chatTokens: current.chatTokens + (update.chatTokens || 0),
    voiceTokens: current.voiceTokens + (update.voiceTokens || 0),
    imageTokens: current.imageTokens + (update.imageTokens || 0),
    minutesUsed: current.minutesUsed + (update.minutesUsed || 0),
    apiCalls: current.apiCalls + (update.apiCalls || 0),
  };

  // Update daily aggregates
  const historyIndex = updated.dailyHistory.findIndex(h => h.date === dateStr);
  if (historyIndex > -1) {
    updated.dailyHistory[historyIndex].tokens += (update.totalTokens || 0);
    updated.dailyHistory[historyIndex].calls += (update.apiCalls || 0);
  } else {
    updated.dailyHistory.push({
      date: dateStr,
      tokens: update.totalTokens || 0,
      calls: update.apiCalls || 0
    });
    if (updated.dailyHistory.length > 30) updated.dailyHistory.shift();
  }

  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
};

export const generateInvoice = (): BillingInvoice => {
  const stats = getUsageStats();
  const invoice: BillingInvoice = {
    id: `INV-${Date.now().toString().slice(-6)}`,
    date: new Date().toLocaleDateString(),
    amount: stats.costEstimate,
    tokens: stats.totalTokens,
    status: 'Draft'
  };

  const updatedStats = {
    ...stats,
    billingHistory: [invoice, ...(stats.billingHistory || [])]
  };

  localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedStats));
  return invoice;
};

export const resetUsage = () => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_STATS));
};

