import { GoogleGenAI, LiveServerMessage, Modality, GenerateContentResponse } from "@google/genai";
import { getSystemInstruction, TOOLS } from "../constants";
import { createBlob, decodeAudioData, decode, encode, base64ToUint8Array, blobToBase64, pcmToWavBlob } from "../utils/audioUtils";
import { Language, VoiceName } from "../types";
import { trackUsage } from "./usageService";

// Helper for stateless reset
export const resetChatSession = () => {
  // Stateless implementation doesn't require reset, but keeping for compatibility
};

/**
 * Sends a message to Gemini using the generateContentStream API.
 */
export async function* sendMessageToGemini(
  message: string,
  emergencyMode: boolean = false,
  language: Language = 'en',
  onToolSuccess?: (toolName: string, result: any) => void
) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let instructions = getSystemInstruction(language);
  if (emergencyMode) {
    instructions += "\n\n[SYSTEM OVERRIDE: EMERGENCY MODE ACTIVE]. Respond concisely. Prioritize safety protocols immediately.";
  }

  const responseStream = await ai.models.generateContentStream({
    model: 'gemini-3-flash-preview',
    contents: [{ role: 'user', parts: [{ text: message }] }],
    config: {
      systemInstruction: instructions,
      tools: [{ functionDeclarations: TOOLS }],
    },
  });

  for await (const chunk of responseStream) {
    const c = chunk as GenerateContentResponse;
    if (c.usageMetadata) {
      const totalTokens = c.usageMetadata.totalTokenCount;
      trackUsage({
        totalTokens: totalTokens,
        chatTokens: totalTokens,
        apiCalls: 1
      });
    }

    const part = c.candidates?.[0]?.content?.parts?.find(p => p.functionCall);
    if (part && part.functionCall) {
      if (onToolSuccess) {
        onToolSuccess(part.functionCall.name, part.functionCall.args);
      }
    }
    yield c;
  }
}

/**
 * Text-to-speech using Gemini 2.5 Flash TTS model.
 */
export const playGeminiTTS = async (text: string, voiceName: VoiceName) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voiceName as any },
        },
      },
    },
  });

  if (response.usageMetadata) {
    trackUsage({
      totalTokens: response.usageMetadata.totalTokenCount,
      voiceTokens: response.usageMetadata.totalTokenCount,
      apiCalls: 1
    });
  }

  const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
  const base64Audio = audioPart?.inlineData?.data;
  if (base64Audio) {
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioBuffer = await decodeAudioData(decode(base64Audio), audioContext, 24000, 1);
    const source = audioContext.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioContext.destination);
    source.start();
  }
};

// --- Live API (Voice) Service ---

export interface LiveSessionCallbacks {
  onOpen: () => void;
  onMessage: (text: string | null, audioBuffer: AudioBuffer | null, isInterrupted: boolean) => void;
  onAudioData: (data: Uint8Array) => void; 
  onError: (error: Error) => void;
  onClose: () => void;
  onToolCall: (toolName: string) => void;
  onToolSuccess?: (toolName: string, result: any) => void;
}

export const connectLiveSession = async (
    callbacks: LiveSessionCallbacks, 
    emergencyMode: boolean = false, 
    language: Language = 'en',
    voiceName: VoiceName = 'Kore'
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const startTime = Date.now();

  const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
  const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

  const analyser = outputAudioContext.createAnalyser();
  analyser.fftSize = 64; 
  const dataArray = new Uint8Array(analyser.frequencyBinCount);
  analyser.connect(outputAudioContext.destination);

  const visualizerInterval = setInterval(() => {
    analyser.getByteFrequencyData(dataArray);
    callbacks.onAudioData(new Uint8Array(dataArray));
  }, 50);

  let nextStartTime = 0;
  const sources = new Set<AudioBufferSourceNode>();
  const audioChunks: Uint8Array[] = [];

  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch (err) {
    callbacks.onError(new Error("MIC_NOT_FOUND"));
    return null;
  }

  await inputAudioContext.resume();
  await outputAudioContext.resume();

  let instructions = getSystemInstruction(language);
  if (emergencyMode) {
    instructions += "\n\n[SYSTEM OVERRIDE: EMERGENCY MODE ACTIVE]. Respond concisely. Prioritize safety protocols immediately.";
  }

  const sessionPromise = ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks: {
      onopen: () => {
        callbacks.onOpen();
        const source = inputAudioContext.createMediaStreamSource(stream);
        const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
        scriptProcessor.onaudioprocess = (event) => {
          const inputData = event.inputBuffer.getChannelData(0);
          const int16 = new Int16Array(inputData.length);
          for (let i = 0; i < inputData.length; i++) {
            int16[i] = inputData[i] * 32768;
          }
          const pcmData = encode(new Uint8Array(int16.buffer));
          sessionPromise.then(s => s.sendRealtimeInput({ media: { mimeType: 'audio/pcm;rate=16000', data: pcmData } }));
        };
        source.connect(scriptProcessor);
        scriptProcessor.connect(inputAudioContext.destination);
      },
      onmessage: async (message: LiveServerMessage) => {
        const parts = message.serverContent?.modelTurn?.parts;
        const base64Audio = parts?.[0]?.inlineData?.data;

        if (base64Audio) {
            const audioData = decode(base64Audio);
            audioChunks.push(audioData);
            nextStartTime = Math.max(nextStartTime, outputAudioContext.currentTime);
            const audioBuffer = await decodeAudioData(audioData, outputAudioContext, 24000, 1);
            const source = outputAudioContext.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(analyser); 
            source.start(nextStartTime);
            nextStartTime += audioBuffer.duration;
            sources.add(source);
            source.onended = () => sources.delete(source);
        }

        const interrupted = message.serverContent?.interrupted;
        if (interrupted) {
          for (const source of sources.values()) {
            try { source.stop(); } catch(e) {}
            sources.delete(source);
          }
          nextStartTime = 0;
        }

        if (message.toolCall) {
          for (const fc of message.toolCall.functionCalls) {
            callbacks.onToolCall(fc.name);
            if (callbacks.onToolSuccess) {
              callbacks.onToolSuccess(fc.name, { status: 'success', ...fc.args });
            }
            sessionPromise.then(s => s.sendToolResponse({
              functionResponses: [{
                id: fc.id,
                name: fc.name,
                response: { result: "ok" }
              }]
            }));
          }
        }
        callbacks.onMessage(null, null, !!interrupted);
      },
      onerror: () => callbacks.onError(new Error("CONNECTION_ERROR")),
      onclose: () => {
        const durationMin = (Date.now() - startTime) / 60000;
        trackUsage({
          minutesUsed: durationMin,
          apiCalls: 1
        });
        callbacks.onClose();
        clearInterval(visualizerInterval);
      }
    },
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceName as any } }
      },
      systemInstruction: instructions,
      tools: [{ functionDeclarations: TOOLS }]
    }
  });

  return {
    disconnect: async () => {
      clearInterval(visualizerInterval);
      sessionPromise.then(s => s.close());
      if (stream) stream.getTracks().forEach(t => t.stop());
      inputAudioContext.close();
      outputAudioContext.close();
    },
    getAudioBlob: () => pcmToWavBlob(audioChunks, 24000)
  };
};

import { UsageStats, BillingInvoice } from "../types";

/**
 * AI Power Usage Service (Enterprise SaaS Tier)
 * Calculates underlying costs vs client billing rates.
 */

const STORAGE_KEY = 'unitec_usage_metrics';

// RATES
const CLIENT_RATE_PER_1M_TOKENS = 0.25;  
const CLIENT_RATE_PER_VOICE_MIN = 0.05;  
const ACTUAL_COST_PER_1M_TOKENS = 0.075; 
const ACTUAL_COST_PER_VOICE_MIN = 0.01;  

const INITIAL_STATS: UsageStats = {
  totalTokens: 0,
  chatTokens: 0,
  voiceTokens: 0,
  imageTokens: 0,
  minutesUsed: 0,
  apiCalls: 0,
  limitTokens: 10000000,
  limitMinutes: 5000,
  costEstimate: 0,
  billingHistory: [],
  dailyHistory: []
};

export const getUsageStats = (): UsageStats => {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (!stored) return { ...INITIAL_STATS };

  try {
    const stats = JSON.parse(stored) as UsageStats;
    // Ensure all required fields exist
    stats.billingHistory = stats.billingHistory || [];
    stats.dailyHistory = stats.dailyHistory || [];
    stats.totalTokens = stats.totalTokens || 0;
    stats.minutesUsed = stats.minutesUsed || 0;

    // Calculate what the client owes
    stats.costEstimate = 
      (stats.totalTokens / 1000000) * CLIENT_RATE_PER_1M_TOKENS + 
      (stats.minutesUsed * CLIENT_RATE_PER_VOICE_MIN);

    return stats;
  } catch (e) {
    return { ...INITIAL_STATS };
  }
};

export const getProfitEstimate = (): number => {
  const stats = getUsageStats();
  const actualCost = 
    (stats.totalTokens / 1000000) * ACTUAL_COST_PER_1M_TOKENS + 
    (stats.minutesUsed * ACTUAL_COST_PER_VOICE_MIN);

  return stats.costEstimate - actualCost;
};

export const trackUsage = (update: Partial<Omit<UsageStats, 'costEstimate' | 'dailyHistory' | 'billingHistory'>>) => {
  const current = getUsageStats();
  const dateStr = new Date().toISOString().split('T')[0];

  const updated: UsageStats = {
    ...current,
    totalTokens: (current.totalTokens || 0) + (update.totalTokens || 0),
    chatTokens: (current.chatTokens || 0) + (update.chatTokens || 0),
    voiceTokens: (current.voiceTokens || 0) + (update.voiceTokens || 0),
    imageTokens: (current.imageTokens || 0) + (update.imageTokens || 0),
    minutesUsed: (current.minutesUsed || 0) + (update.minutesUsed || 0),
    apiCalls: (current.apiCalls || 0) + (update.apiCalls || 0),
  };

  const historyIndex = updated.dailyHistory.findIndex(h => h.date === dateStr);
  if (historyIndex > -1) {
    updated.dailyHistory[historyIndex].tokens += (update.totalTokens || 0);
    updated.dailyHistory[historyIndex].calls += (update.apiCalls || 0);
  } else {
    updated.dailyHistory.push({
      date: dateStr,
      tokens: update.totalTokens || 0,
      calls: update.apiCalls || 0
    });
    if (updated.dailyHistory.length > 30) updated.dailyHistory.shift();
  }

  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
};

export const generateInvoice = (): BillingInvoice => {
  const stats = getUsageStats();
  const invoice: BillingInvoice = {
    id: `INV-${Date.now().toString().slice(-6)}`,
    date: new Date().toLocaleDateString(),
    amount: stats.costEstimate,
    tokens: stats.totalTokens,
    status: 'Draft'
  };

  const updatedStats = {
    ...stats,
    billingHistory: [invoice, ...(stats.billingHistory || [])]
  };

  localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedStats));
  return invoice;
};

export const resetUsage = () => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_STATS));
};

