/**
 * Sends a message to Gemini using the generateContentStream API.
 */
export async function* sendMessageToGemini(
  message: string,
  emergencyMode: boolean = false,
  language: Language = 'en',
  onToolSuccess?: (toolName: string, result: any) => void
) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let instructions = getSystemInstruction(language);
  if (emergencyMode) {
    instructions += "\n\n[SYSTEM OVERRIDE: EMERGENCY MODE ACTIVE]. Respond concisely. Prioritize safety protocols immediately.";
  }

  const responseStream = await ai.models.generateContentStream({
    model: 'gemini-3-flash-preview',
    contents: [{ role: 'user', parts: [{ text: message }] }],
    config: {
      systemInstruction: instructions,
      tools: [{ functionDeclarations: TOOLS }],
    },
  });

  for await (const chunk of responseStream) {
    const c = chunk as GenerateContentResponse;
    if (c.usageMetadata) {
      const totalTokens = c.usageMetadata.totalTokenCount;
      trackUsage({
        totalTokens: totalTokens,
        chatTokens: totalTokens,
        apiCalls: 1
      });
    }

    const part = c.candidates?.[0]?.content?.parts?.find(p => p.functionCall);
    if (part && part.functionCall) {
      if (onToolSuccess) {
        onToolSuccess(part.functionCall.name, part.functionCall.args);
      }
    }
    yield c;
  }
}

// --- Live API (Voice & Vision) Service ---

export interface LiveSessionCallbacks {
  onOpen: () => void;
  onMessage: (text: string | null, audioBuffer: AudioBuffer | null, isInterrupted: boolean) => void;
  onAudioData: (data: Uint8Array) => void; 
  onError: (error: Error) => void;
  onClose: () => void;
  onToolCall: (toolName: string) => void;
  onToolSuccess?: (toolName: string, result: any) => void;
}

export const connectLiveSession = async (
    callbacks: LiveSessionCallbacks, 
    emergencyMode: boolean = false, 
    language: Language = 'en',
    voiceName: VoiceName = 'Kore'
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const startTime = Date.now();

  const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
  const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

  const analyser = outputAudioContext.createAnalyser();
  analyser.fftSize = 64; 
  const dataArray = new Uint8Array(analyser.frequencyBinCount);
  analyser.connect(outputAudioContext.destination);

  const visualizerInterval = setInterval(() => {
    analyser.getByteFrequencyData(dataArray);
    callbacks.onAudioData(new Uint8Array(dataArray));
  }, 50);

  let nextStartTime = 0;
  const sources = new Set<AudioBufferSourceNode>();
  const audioChunks: Uint8Array[] = [];

  let stream: MediaStream;
  try {
    // Request both audio and video for the "Live Feed" capability
    stream = await navigator.mediaDevices.getUserMedia({ 
      audio: true,
      video: { width: 640, height: 480, frameRate: 15 }
    });
  } catch (err) {
    // Fallback to audio only if camera is blocked
    try {
      stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch (innerErr) {
      callbacks.onError(new Error("MIC_NOT_FOUND"));
      return null;
    }
  }

  await inputAudioContext.resume();
  await outputAudioContext.resume();

  let instructions = getSystemInstruction(language);
  instructions += "\n\nYou now have VISION capabilities. You can see the user and their environment through the live feed. Comment on what you see if relevant to help with their inquiry (e.g., if they are showing you a damaged panel or a space they want to renovate).";

  if (emergencyMode) {
    instructions += "\n\n[SYSTEM OVERRIDE: EMERGENCY MODE ACTIVE]. Respond concisely. Prioritize safety protocols immediately.";
  }

  const sessionPromise = ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-12-2025',
    callbacks: {
      onopen: () => {
        callbacks.onOpen();
        const source = inputAudioContext.createMediaStreamSource(stream);
        const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
        scriptProcessor.onaudioprocess = (event) => {
          const inputData = event.inputBuffer.getChannelData(0);
          const int16 = new Int16Array(inputData.length);
          for (let i = 0; i < inputData.length; i++) {
            int16[i] = inputData[i] * 32768;
          }
          const pcmData = encode(new Uint8Array(int16.buffer));
          sessionPromise.then(s => s.sendRealtimeInput({ media: { mimeType: 'audio/pcm;rate=16000', data: pcmData } }));
        };
        source.connect(scriptProcessor);
        scriptProcessor.connect(inputAudioContext.destination);
      },
      onmessage: async (message: LiveServerMessage) => {
        const parts = message.serverContent?.modelTurn?.parts;
        const base64Audio = parts?.[0]?.inlineData?.data;

        if (base64Audio) {
            const audioData = decode(base64Audio);
            audioChunks.push(audioData);
            nextStartTime = Math.max(nextStartTime, outputAudioContext.currentTime);
            const audioBuffer = await decodeAudioData(audioData, outputAudioContext, 24000, 1);
            const source = outputAudioContext.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(analyser); 
            source.start(nextStartTime);
            nextStartTime += audioBuffer.duration;
            sources.add(source);
            source.onended = () => sources.delete(source);
        }

        const interrupted = message.serverContent?.interrupted;
        if (interrupted) {
          for (const source of sources.values()) {
            try { source.stop(); } catch(e) {}
            sources.delete(source);
          }
          nextStartTime = 0;
        }

        if (message.toolCall) {
          for (const fc of message.toolCall.functionCalls) {
            callbacks.onToolCall(fc.name);
            if (callbacks.onToolSuccess) {
              callbacks.onToolSuccess(fc.name, { status: 'success', ...fc.args });
            }
            sessionPromise.then(s => s.sendToolResponse({
              functionResponses: [{
                id: fc.id,
                name: fc.name,
                response: { result: "ok" }
              }]
            }));
          }
        }
        callbacks.onMessage(null, null, !!interrupted);
      },
      onerror: () => callbacks.onError(new Error("CONNECTION_ERROR")),
      onclose: () => {
        const durationMin = (Date.now() - startTime) / 60000;
        trackUsage({
          minutesUsed: durationMin,
          apiCalls: 1
        });
        callbacks.onClose();
        clearInterval(visualizerInterval);
      }
    },
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceName as any } }
      },
      systemInstruction: instructions,
      tools: [{ functionDeclarations: TOOLS }]
    }
  });

  return {
    disconnect: async () => {
      clearInterval(visualizerInterval);
      sessionPromise.then(s => s.close());
      if (stream) stream.getTracks().forEach(t => t.stop());
      inputAudioContext.close();
      outputAudioContext.close();
    },
    getAudioBlob: () => pcmToWavBlob(audioChunks, 24000),
    sendFrame: (base64Image: string) => {
      sessionPromise.then(s => s.sendRealtimeInput({
        media: { data: base64Image, mimeType: 'image/jpeg' }
      }));
    },
    stream
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { Mic, Phone, AlertCircle, Loader2, CheckCircle2, Download, Headphones, Camera, CameraOff, Video } from 'lucide-react';
import { connectLiveSession, sendMessageToGemini } from '../services/geminiService';
import { playDeepgramTTS } from '../services/deepgramService';
import AudioVisualizer from './AudioVisualizer';
import { Language, VoiceName, VoiceProvider, CallRecording } from '../types';
import { UI_TRANSLATIONS } from '../constants';
import { blobToBase64 } from '../utils/audioUtils';

interface CallTabProps {
  emergencyMode?: boolean;
  language: Language;
  voiceName: VoiceName;
  voiceProvider: VoiceProvider;
  deepgramKey?: string;
}

const CallTab: React.FC<CallTabProps> = ({ emergencyMode, language, voiceName, voiceProvider, deepgramKey }) => {
  const t = UI_TRANSLATIONS[language];

  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error' | 'listening' | 'processing' | 'speaking'>('idle');
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [audioData, setAudioData] = useState<Uint8Array>(new Uint8Array(64));
  const [activeTool, setActiveTool] = useState<string | null>(null);
  const [isCameraActive, setIsCameraActive] = useState(true);

  const [showBookingConfirmation, setShowBookingConfirmation] = useState(false);
  const [confirmedDate, setConfirmedDate] = useState<string | null>(null);
  const [lastRecordingUrl, setLastRecordingUrl] = useState<string | null>(null);

  // Refs
  const sessionControllerRef = useRef<any>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frameIntervalRef = useRef<number | null>(null);

  // Hybrid Mode Refs
  const recognitionRef = useRef<any>(null);
  const currentAudioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animationFrameRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      stopAll();
    };
  }, []);

  const stopAll = async () => {
    if (frameIntervalRef.current) {
      clearInterval(frameIntervalRef.current);
      frameIntervalRef.current = null;
    }
    if (sessionControllerRef.current) {
      await sessionControllerRef.current.disconnect();
      sessionControllerRef.current = null;
    }
    if (recognitionRef.current) {
        recognitionRef.current.stop();
        recognitionRef.current = null;
    }
    if (currentAudioRef.current) {
        currentAudioRef.current.pause();
        currentAudioRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
  };

  const startVisualizer = (stream: MediaStream | HTMLMediaElement) => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    const ctx = audioContextRef.current;
    if (analyserRef.current) analyserRef.current.disconnect();

    const analyser = ctx.createAnalyser();
    analyser.fftSize = 64;
    analyserRef.current = analyser;

    let source;
    if (stream instanceof MediaStream) {
      source = ctx.createMediaStreamSource(stream);
    } else {
      source = ctx.createMediaElementSource(stream);
      source.connect(ctx.destination);
    }
    source.connect(analyser);

    const dataArray = new Uint8Array(analyser.frequencyBinCount);
    const update = () => {
      analyser.getByteFrequencyData(dataArray);
      setAudioData(new Uint8Array(dataArray));
      animationFrameRef.current = requestAnimationFrame(update);
    };
    update();
  };

  const initSpeechRecognition = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      throw new Error("SPEECH_NOT_SUPPORTED");
    }

    const recognition = new SpeechRecognition();
    recognition.lang = language === 'en' ? 'en-US' : 'es-ES';
    recognition.interimResults = false;
    recognition.continuous = false;

    recognition.onstart = () => setStatus('listening');
    recognition.onresult = async (event: any) => {
      const transcript = event.results[0][0].transcript;
      if (transcript) {
        handleHybridProcess(transcript);
      }
    };
    recognition.onerror = () => {
      if (status !== 'idle') recognition.start();
    };
    recognition.onend = () => {
      if (status === 'listening') recognition.start();
    };

    recognitionRef.current = recognition;
    recognition.start();
  };

  const handleHybridProcess = async (text: string) => {
    setStatus('processing');
    if (recognitionRef.current) recognitionRef.current.stop();

    try {
      let fullResponse = "";
      const responseGenerator = sendMessageToGemini(
        text, 
        emergencyMode, 
        language,
        (toolName, result) => {
          if (toolName === 'book_appointment') {
            setConfirmedDate(result.date || null);
            setShowBookingConfirmation(true);
          }
          setActiveTool(toolName);
        }
      );

      for await (const chunk of responseGenerator) {
        fullResponse += chunk.text || "";
      }

      if (fullResponse) {
        if (!deepgramKey) throw new Error("API_KEY_MISSING");

        setStatus('speaking');
        const audio = await playDeepgramTTS(
          fullResponse, 
          deepgramKey, 
          voiceName,
          () => {}, // onStart
          () => { // onEnd
            setStatus('listening');
            if (recognitionRef.current) recognitionRef.current.start();
          }
        );

        if (audio) {
          currentAudioRef.current = audio;
          startVisualizer(audio);
        }
      } else {
        setStatus('listening');
        if (recognitionRef.current) recognitionRef.current.start();
      }
    } catch (err: any) {
      setErrorMessage(mapErrorToUserMessage(err));
      setStatus('error');
    }
  };

  const handleStartCall = async () => {
    setErrorMessage('');
    if (lastRecordingUrl) {
        URL.revokeObjectURL(lastRecordingUrl);
        setLastRecordingUrl(null);
    }

    if (voiceProvider === 'deepgram') {
        if (!deepgramKey) {
          setErrorMessage(language === 'en' ? "Deepgram API Key is required." : "Se requiere la API Key de Deepgram.");
          setStatus('error');
          return;
        }
        setStatus('connecting');
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ 
            audio: true, 
            video: isCameraActive ? { width: 480, height: 360 } : false 
          });

          if (videoRef.current && isCameraActive) {
            videoRef.current.srcObject = stream;
          }

          startVisualizer(stream);
          initSpeechRecognition();
          setStatus('connected');
          setStatus('listening');
        } catch (e: any) {
          setErrorMessage(mapErrorToUserMessage(e));
          setStatus('error');
        }
    } else {
        setStatus('connecting');
        try {
            const session = await connectLiveSession({
                onOpen: () => {
                  setStatus('connected');
                  startFrameStreaming();
                },
                onMessage: () => {},
                onAudioData: (data) => setAudioData(data),
                onToolCall: (name) => setActiveTool(name),
                onToolSuccess: (name, res) => {
                     if (name === 'book_appointment') {
                        setConfirmedDate(res.date || null);
                        setShowBookingConfirmation(true);
                     }
                },
                onError: (err) => {
                    setErrorMessage(mapErrorToUserMessage(err));
                    setStatus('error');
                },
                onClose: () => setStatus('idle')
            }, emergencyMode, language, voiceName);

            if (session) {
                sessionControllerRef.current = session;
                if (videoRef.current && session.stream) {
                  videoRef.current.srcObject = session.stream;
                }
            }
        } catch (e: any) {
            setErrorMessage(mapErrorToUserMessage(e));
            setStatus('error');
        }
    }
  };

  const startFrameStreaming = () => {
    if (!canvasRef.current || !videoRef.current) return;

    frameIntervalRef.current = window.setInterval(() => {
      const canvas = canvasRef.current;
      const video = videoRef.current;
      if (!canvas || !video || video.paused || video.ended) return;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // Draw current video frame to hidden canvas
      canvas.width = video.videoWidth / 2; // scale down for performance
      canvas.height = video.videoHeight / 2;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      canvas.toBlob(async (blob) => {
        if (blob && sessionControllerRef.current?.sendFrame) {
          const base64 = await blobToBase64(blob);
          sessionControllerRef.current.sendFrame(base64);
        }
      }, 'image/jpeg', 0.6); // medium quality
    }, 1000); // Send 1 frame per second
  };

  const handleEndCall = async () => {
    if (sessionControllerRef.current) {
      const blob = sessionControllerRef.current.getAudioBlob();
      if (blob.size > 100) {
          const url = URL.createObjectURL(blob);
          setLastRecordingUrl(url);
          saveToLibrary(blob);
      }
    }
    await stopAll();
    setStatus('idle');
  };

  const mapErrorToUserMessage = (error: any): string => {
    const msg = error.message || String(error);
    if (language === 'en') {
        if (msg.includes("API_KEY_MISSING")) return "Config Error: Key missing.";
        if (msg.includes("MIC_PERMISSION_DENIED")) return "Mic access denied.";
        return "Unexpected error.";
    } else {
        if (msg.includes("API_KEY_MISSING")) return "Error: Falta Key.";
        return "Error inesperado.";
    }
  };

  const saveToLibrary = (blob: Blob) => {
    const id = Date.now().toString();
    const newRecording: CallRecording = {
        id,
        name: `Call_${id.slice(-4)}.wav`,
        timestamp: new Date().toISOString(),
        duration: "0:30"
    };

    const stored = localStorage.getItem('unitec_call_library') || '[]';
    const library = JSON.parse(stored);
    library.unshift(newRecording);
    localStorage.setItem('unitec_call_library', JSON.stringify(library));
  };

  const toggleCamera = () => {
    const newState = !isCameraActive;
    setIsCameraActive(newState);
    if (sessionControllerRef.current?.stream) {
      const videoTrack = sessionControllerRef.current.stream.getVideoTracks()[0];
      if (videoTrack) videoTrack.enabled = newState;
    }
  };

  const isActive = status === 'connected' || status === 'listening' || status === 'speaking' || status === 'processing';

  return (
    <div className="h-full flex flex-col bg-slate-50 relative overflow-hidden font-sans">

      {/* Top Status Area */}
      <div className="pt-6 pb-2 text-center z-10 px-6 transition-opacity duration-300">
        <div className="flex justify-center items-center gap-2 mb-1">
             <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t.voiceTitle}</h2>
             <span className={`text-[9px] px-1.5 py-0.5 rounded-full border font-black uppercase ${
                 voiceProvider === 'deepgram' 
                 ? 'bg-purple-100 text-purple-700 border-purple-200' 
                 : 'bg-blue-100 text-blue-700 border-blue-200'
             }`}>
                 {voiceProvider === 'deepgram' ? 'Hybrid' : 'Native + Vision'}
             </span>
        </div>
        <div className={`text-lg font-bold tracking-tight px-4 transition-colors duration-300 ${
            status === 'error' ? 'text-red-600' : 
            isActive ? 'text-slate-900' : 'text-slate-500'
        }`}>
          {status === 'idle' && t.tapToStart}
          {status === 'connecting' && <span className="animate-pulse">{t.connecting}</span>}
          {status === 'connected' && t.connected}
          {status === 'listening' && (language === 'en' ? "I'm listening..." : "Escuchando...")}
          {status === 'processing' && (language === 'en' ? "Thinking..." : "Pensando...")}
          {status === 'speaking' && (language === 'en' ? "Speaking..." : "Hablando...")}
          {status === 'error' && (errorMessage || t.connectionFailed)}
        </div>
      </div>

      {/* Main Content (Live Feed + Visualizer) */}
      <div className="flex-1 relative flex flex-col items-center justify-center min-h-[300px] p-4">

        {/* Hidden Canvas for frame processing */}
        <canvas ref={canvasRef} className="hidden" />

        {/* Live Feed Container */}
        <div className={`relative transition-all duration-700 transform ${isActive ? 'scale-100 opacity-100 mb-6' : 'scale-75 opacity-0 pointer-events-none'}`}>
             <div className="w-56 h-56 md:w-64 md:h-64 rounded-[40px] overflow-hidden bg-slate-200 shadow-2xl border-4 border-white ring-1 ring-slate-200 relative group">
                <video 
                  ref={videoRef} 
                  autoPlay 
                  playsInline 
                  muted 
                  className={`w-full h-full object-cover grayscale-[0.2] contrast-[1.1] transition-opacity duration-500 ${isCameraActive ? 'opacity-100' : 'opacity-0'}`}
                />
                {!isCameraActive && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-800 text-slate-400">
                    <CameraOff size={48} className="opacity-20 mb-2" />
                    <span className="text-[10px] font-bold uppercase tracking-widest">Feed Disabled</span>
                  </div>
                )}
                {/* Visualizer overlay on bottom of video */}
                <div className="absolute bottom-0 left-0 right-0 h-16 bg-gradient-to-t from-black/40 to-transparent flex items-center justify-center px-6">
                    <AudioVisualizer audioData={audioData} isActive={isActive} />
                </div>
             </div>
        </div>

        {/* Success Banner */}
        <div className={`absolute top-0 z-40 transition-all duration-500 transform w-full px-6 flex justify-center ${
            showBookingConfirmation ? 'translate-y-4 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'
        }`}>
            <div className="bg-emerald-600/90 backdrop-blur-md text-white px-5 py-2.5 rounded-2xl shadow-xl flex items-center gap-3 border border-white/20">
                <CheckCircle2 size={18} />
                <div>
                   <p className="text-[11px] font-bold">{t.bookingConfirmed}</p>
                   {confirmedDate && <p className="text-[9px] opacity-80">{confirmedDate}</p>}
                </div>
            </div>
        </div>

        {!isActive && (
          <div className="relative z-10 w-full flex flex-col items-center justify-center space-y-8">
              <div className="h-[80px] w-full flex items-center justify-center px-8">
                  <AudioVisualizer audioData={audioData} isActive={isActive} />
              </div>

              {/* Main Start Button */}
              <div className="relative group">
                  <div 
                      onClick={handleStartCall}
                      className="relative w-24 h-24 rounded-full flex items-center justify-center transition-all duration-700 shadow-2xl overflow-hidden btn-grass cursor-pointer hover:scale-105 active:scale-90"
                  >
                      <div className="absolute inset-0 grass-texture opacity-30"></div>
                      {status === 'connecting' ? (
                           <Loader2 size={32} className="text-white animate-spin" />
                      ) : (
                          <Mic size={32} className="text-white" />
                      )}
                  </div>
              </div>
          </div>
        )}
      </div>

      {/* Controls Area */}
      <div className="w-full px-6 pb-8 pt-2 space-y-4 shrink-0 z-10">
        {status === 'idle' && lastRecordingUrl && (
            <div className="flex justify-center mb-2 animate-in fade-in slide-in-from-bottom-2">
                <a
