    const storedLib = localStorage.getItem('unitec_call_library');
    if (storedLib) setRecordings(JSON.parse(storedLib));
    setEscalaConfig(getEscalaConfig());

    // Load Training Data
    const storedTraining = localStorage.getItem('unitec_training_data');
