      {/* Bottom Navigation */}
      <nav className={`h-20 bg-white border-t border-slate-100 flex items-center justify-around px-2 shrink-0 pb-safe shadow-[0_-4px_12px_rgba(0,0,0,0.03)] ${!isEmbedMode ? 'md:rounded-b-[32px]' : ''}`}>
