                if (name === 'book_appointment') {
                    setConfirmedDate(res.date || null);
                    setShowBookingConfirmation(true);
                }
            }, customGreeting);

            let fullText = "";
            for await (const chunk of responseGen) {
                 const c = chunk as GenerateContentResponse;
                 if (c.text) fullText += c.text;
            }

            if (fullText) {
                setStatus('speaking');
